// EA12.6.1 Describe at least two aspects of Earth science that make it different from other sciences
// Source: June 2007 public exam, item 1.
E("es-u1-61-q01",1,["EA12.6.1"],1,"var",varset([function(){return mcq("Which branch of earth science studies the salinity of marine environments?","oceanography",["astronomy","geology","meteorology"],"Oceanography is the study of the oceans, including the composition and movements of sea water; salinity is a property of sea water.",{});}]),["Salinity is a property of ocean water."]);

// Source: June 2008 public exam, item 2.
E("es-u1-61-q02",1,["EA12.6.1"],1,"var",varset([function(){return mcq("Which branch of earth science involves the analysis of earthquake waves?","seismology",["hydrology","mineralogy","volcanology"],"Seismology is the study of earthquakes and the seismic waves they generate, so earthquake waves are analysed by seismologists.",{});}]),["The prefix comes from the Greek word for shaking."]);

// Source: June 2009 public exam, item 2.
E("es-u1-61-q03",1,["EA12.6.1"],1,"var",varset([function(){return mcq("Which branch of Earth Science studies the arrangement of atoms in minerals?","crystallography",["geomorphology","hydrology","petrology"],"Crystallography studies how atoms are arranged in minerals, which determines their crystal form and properties. It is one of the specialized fields listed in the curriculum guide for this indicator.",{});}]),["Think of the crystal structure of a mineral."]);

// Source: August 2006 public exam, item 1.
E("es-u1-61-q04",1,["EA12.6.1"],1,"var",varset([function(){return mcq("In which branch of Earth Science is ancient life studied?","paleontology",["climatology","meteorology","volcanology"],"Paleontology is the study of ancient life, chiefly through the fossil record; it links Earth science to biology.",{});}]),["Fossils are the main evidence used."]);

// Source: August 2007 public exam, item 1.
E("es-u1-61-q05",1,["EA12.6.1"],1,"var",varset([function(){return mcq("Which branch of Earth Science studies the composition of extrusive igneous rocks?","volcanology",["hydrology","oceanography","paleontology"],"Extrusive igneous rocks form from lava erupted at the surface, so their composition is studied within volcanology, the study of volcanic activity.",{});}]),["Extrusive rocks come from volcanoes."]);

// Source: August 2008 public exam, item 2.
E("es-u1-61-q06",1,["EA12.6.1"],1,"var",varset([function(){return mcq("Which branch of earth science is studied when a geologist and biologist work together?","paleontology",["astronomy","meteorology","mineralogy"],"Paleontology studies ancient life through fossils, so it sits where geology meets biology: the geologist supplies the rock record and the biologist the knowledge of living things. Earth science routinely draws on the other sciences in this way.",{});}]),["Which field deals with life in the rock record?"]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.6.1.
E("es-u1-61-q07",1,["EA12.6.1"],2,"var",varset([function(){return mcq("Which statement describes an aspect of Earth science that makes it different from the other sciences?","It draws on all of the other sciences to help explain Earth's environment.",["It relies only on direct observation of Earth's interior.","It is carried out entirely within a laboratory setting.","It explains present-day processes without reference to the past."],"Earth science is built from the other sciences: it uses physics, chemistry, biology, astronomy and mathematics together to understand Earth's environment, rather than standing apart from them.",{});}]),["Think about how many other sciences feed into the study of Earth."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.6.1.
E("es-u1-61-q08",1,["EA12.6.1"],1,"var",varset([function(){return mcq("Earth science differs from many other sciences in that its explanations must account for","events sequenced over vast amounts of geologic time",["the behaviour of materials at extremely high speeds","the interactions of subatomic particles in isolation","the growth of organisms over a single lifetime"],"Earth science requires consideration of vast amounts of time: events must be placed in sequence (chronology) and assigned ages across billions of years of Earth history, a demand few other sciences share.",{});}]),["Earth history runs to billions of years."]);

// EA12.1.1 Describe the four stages of the nebular hypothesis that led to the formation of our solar system
// Source: June 2006 public exam, item 2.
E("es-u1-11-q01",1,["EA12.1.1"],1,"var",varset([function(){return mcq("According to modern theory, approximately how many years ago did the solar nebula form?","5 billion",["20 billion","250 million","600 million"],"The solar nebula, the cloud of dust and gas from which the solar system formed, began to contract approximately 5 billion years ago.",{});}]),["The workbook dates stage 1 of the nebular hypothesis to about this long ago."]);

// Source: June 2007 public exam, item 2.
E("es-u1-11-q02",1,["EA12.1.1"],1,"var",varset([function(){return mcq("Which theory describes the origin of the solar system?","Nebular theory",["Big Bang theory","Catastrophism","Evolution"],"The Nebular theory describes the formation of the solar system from a rotating cloud of dust and gas. The Big Bang theory addresses the origin of the universe as a whole, a much larger question.",{});}]),["The name comes from the Latin word for cloud."]);

// Source: June 2009 public exam, item 6.
E("es-u1-11-q03",1,["EA12.1.1"],1,"var",varset([function(){return mcq("What refers to the process by which the solar system forms from dust and gases in space?","nebular hypothesis",["accretion","differentiation","segregation"],"The nebular hypothesis is the process by which the solar system formed from a cloud of dust and gases in space. Accretion is one step within it, when particles collided and stuck together to build the planets.",{});}]),["It is named for the cloud the solar system formed from."]);

// Source: Sample final exam, item 2.
E("es-u1-11-q04",1,["EA12.1.1"],3,"var",varset([function(){var q=mcq("Which sequence of events produced the solar system according to the Nebular Hypothesis?","C, A, B, D",["A, B, D, C","A, D, C, B","C, B, D, A"],"Panel C shows the nebula contracting, with arrows pointing inward. In panel A the cloud is rotating and flattening, with material concentrating at the centre where the sun forms. Panels B and D then show the flattened disk, in which the remaining material collected and accreted into planets.",{});q.figure="<img src=\"banks/earth-3209/assets/u1-11-final-02.png\" alt=\"Four panels labelled A, B, C and D showing stages in the formation of the solar system: A is a bright rotating flattened cloud, B is a ringed disk seen at an angle, C is a cloud with arrows pointing inward, and D is a ringed disk seen from above with a bright centre.\">";return q;}]),["Start with the panel whose arrows point inward."]);

// Source: Authored for this bank from the four stages as set out in the Woodland workbook, Unit 1, Lesson 2.
E("es-u1-11-q05",1,["EA12.1.1"],2,"var",varset([function(){return mcq("According to the solar nebular hypothesis, what happens during the third stage of the solar system's formation?","Particles in the cooling disk collide and accrete to form the planets and moons",["The cloud of dust and gas begins to contract under its own gravity","Material concentrates at the centre of the disk and heats up to form the sun","Solar winds sweep the remaining debris out of the disk into space"],"In stage 1 the nebula contracts under gravity and rotates faster; in stage 2 material concentrates at the centre and forms the sun, leaving a flattened disk; in stage 3 the disk cools and its particles collide and accrete into planets and moons; in stage 4 solar winds clear the remaining debris.",{});}]),["Stage 3 is where the planets themselves are built."]);

// Source: Rewritten from the Woodland workbook, Unit 1, Lesson 2, Sample Problem 1, whose printed options were not recoverable.
E("es-u1-11-q06",1,["EA12.1.1"],2,"var",varset([function(){return mcq("Which sequence correctly orders the stages of the solar nebular hypothesis from first to last?","the nebula contracts and rotates; the disk flattens and the sun forms; particles accrete into planets; debris is swept away",["the disk flattens and the sun forms; the nebula contracts and rotates; particles accrete into planets; debris is swept away","the nebula contracts and rotates; particles accrete into planets; the disk flattens and the sun forms; debris is swept away","debris is swept away; the nebula contracts and rotates; the disk flattens and the sun forms; particles accrete into planets"],"The stages run in order: the nebula contracts under gravity and spins faster; rotation flattens it into a disk while material concentrated at the centre forms the sun; particles in the cooling disk collide and accrete into planets; finally, solar winds sweep away most of the remaining debris.",{});}]),["Nothing can be swept away until the planets exist."]);

// EA12.6.2 Explain the roles of evidence, theories and paradigms in the development of scientific knowledge
// Source: June 2008 public exam, item 1.
E("es-u1-62-q01",1,["EA12.6.2"],1,"var",varset([function(){return mcq("Which refers to a well tested and widely accepted explanation of observed natural phenomena?","theory",["hypothesis","law","paradigm"],"A theory is an explanation of natural phenomena that has been well tested and is widely accepted. A hypothesis is still untested, and a law describes what happens rather than explaining it.",{});}]),["It has survived extensive testing."]);

// Source: June 2009 public exam, item 1.
E("es-u1-62-q02",1,["EA12.6.2"],1,"var",varset([function(){return mcq("What is an untested explanation of a naturally occurring phenomenon?","hypothesis",["fact","law","theory"],"A hypothesis is a preliminary, untested explanation proposed for an observed phenomenon; it must go through extensive testing before it can be accepted.",{});}]),["It comes before testing in the development of scientific knowledge."]);

// Source: August 2008 public exam, item 1.
E("es-u1-62-q03",1,["EA12.6.2"],1,"var",varset([function(){return mcq("Which is a formal statement in which a natural phenomena is described under given conditions?","law",["evidence","hypothesis","paradigm"],"A scientific law is a formal statement describing how nature behaves under given conditions, generalized from observations and experiments with no known deviation.",{});}]),["It describes behaviour rather than explaining it."]);

// Source: Rewritten from the Woodland workbook, Unit 1, Lesson 1, Sample Problem 5.
E("es-u1-62-q04",1,["EA12.6.2"],2,"var",varset([function(){return mcq("Which scientific concept has the highest degree of certainty?","law",["hypothesis","observation","theory"],"A law is a generalization about the behaviour of nature from which there has been no known deviation after numerous observations and experiments, so it carries the highest degree of certainty of the four. A theory, however well tested, remains an explanation that new evidence could revise.",{});}]),["Which one has never been observed to fail?"]);

// Source: Authored for this bank from the curriculum guide's STSE component for EA12.6.2, The Search for Other Solar Systems.
E("es-u1-62-q05",1,["EA12.6.2"],2,"var",varset([function(){return mcq("Astronomers once assumed that other solar systems would be arranged much like our own. Observations of newly discovered solar systems show arrangements the accepted explanation cannot account for. What is the most likely result?","The explanation is revised, or replaced as a new paradigm develops",["The new observations are set aside because the explanation is already accepted","The explanation immediately becomes a scientific law","The observations are repeated until they agree with the explanation"],"Evidence is the test of a theory. When observations accumulate that an accepted explanation cannot account for, scientists revise the explanation, and a sufficiently different replacement amounts to a new paradigm. This is the situation the search for other solar systems created for the nebular model.",{});}]),["Evidence outranks an accepted explanation."]);

// EA12.1.2 Describe the formation and segregation of Earth layers
// Source: June 2006 public exam, item 9.
E("es-u1-12-q01",1,["EA12.1.2"],2,"var",varset([function(){var q=mcq("Which factors contribute to the unique composition of D?","radioactive decay and gravitational forces",["geothermal energy and accretion","geothermal energy and gravitational forces","radioactive decay and accretion"],"Layer D is the inner core. Heat from radioactive decay helped melt the young Earth's interior, and gravitational forces then pulled the dense elements, nickel and iron, toward the centre, giving the inner core its unique composition.",{});q.figure="<img src=\"banks/earth-3209/assets/u1-13-jun06-08.png\" alt=\"Cross-section diagram of Earth's interior with four labelled regions: A in the upper mantle just below the crust, B the mantle, C the outer core and D the inner core at the centre.\">";return q;}]),["D is the layer at Earth's centre."]);

// Source: Sample final exam, item 3.
E("es-u1-12-q02",1,["EA12.1.2"],1,"var",varset([function(){return mcq("Which is an internal heat source that contributed to Earth's layered structure?","radioactive decay",["convection currents","hot spots","seismic waves"],"Radioactive decay inside the young Earth released heat that helped melt its interior; once molten, the material could segregate by density into layers. Convection currents and hot spots are results of the internal heat, not sources of it.",{});}]),["The layering required the interior to melt first."]);

// Source: Sample final exam, item 5.
E("es-u1-12-q03",1,["EA12.1.2"],2,"var",varset([function(){return mcq("Which processes are responsible for Earth's layers? 1. Heat from particle collisions 2. Regional metamorphism 3. Gravitational forces 4. Compaction and cementation","1 and 3",["1 and 2","3 and 2","3 and 4"],"Heat from particle collisions (with radioactive decay) melted the young Earth's interior, and gravitational forces then sorted the molten material by density: dense nickel and iron sank to the centre while lighter rock rose. Regional metamorphism and compaction and cementation act on rocks at or near the surface and did not create the layers.",{});}]),["One process supplied the heat; the other did the sorting."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.1.2.
E("es-u1-12-q04",1,["EA12.1.2"],1,"var",varset([function(){return mcq("What first had to happen to the young Earth before its materials could separate into layers?","Its interior had to melt from heat generated inside it",["Its surface had to cool into a solid crust of rock","Its oceans had to condense from water vapour in the air","Its atmosphere had to form from volcanic gases"],"Segregation is a sorting of material by density, and solid rock cannot sort itself. Heat from particle collisions and the decay of radioactive elements first melted the interior; only then could gravity pull dense material toward the centre and force lighter material upward.",{});}]),["Density sorting needs material that can move."]);

// Source: Authored for this bank, applying the segregation model of the August 2008 and sample final exams to a new case.
E("es-u1-12-q05",1,["EA12.1.2"],3,"var",varset([function(){return mcq("A newly discovered planet is found to have the same composition throughout its interior, with dense iron-rich material still present near its surface. Which statement best explains the planet's structure?","Its interior never melted, so segregation by density could not occur",["Its gravity is too weak to hold an atmosphere in place","Its core cooled and solidified before its mantle formed","Its layers were mixed together by the impact that formed it"],"Segregation requires a molten interior: heat melts the planet, gravity sinks the dense material and floats the light material, and layers result. A planet whose interior never melted keeps the unsorted composition it formed with, dense material near the surface included.",{});}]),["Work through what segregation needs in order to happen."]);

// EA12.1.3 Identify the various Earth layers
// Source: June 2006 public exam, item 7.
E("es-u1-13-q01",1,["EA12.1.3"],2,"var",varset([function(){return mcq("Which best explains the difference in density between the inner core and the lithosphere?","composition",["crystallization","porosity","thickness"],"The inner core is far denser than the lithosphere because of what each is made of: segregation concentrated dense nickel and iron at the centre, while the lithosphere is made of much lighter rock.",{});}]),["Think about what each layer is made of."]);

// Source: June 2006 public exam, item 8.
E("es-u1-13-q02",1,["EA12.1.3"],1,"var",varset([function(){var q=mcq("Which layer contains the asthenosphere?","A",["B","C","D"],"The asthenosphere is the weak, plastic upper part of the mantle, in the zone labelled A on the diagram, directly below the crust.",{});q.figure="<img src=\"banks/earth-3209/assets/u1-13-jun06-08.png\" alt=\"Cross-section diagram of Earth's interior with four labelled regions: A in the upper mantle just below the crust, B the mantle, C the outer core and D the inner core at the centre.\">";return q;}]),["The asthenosphere is part of the upper mantle."]);

// Source: June 2007 public exam, item 8.
E("es-u1-13-q03",1,["EA12.1.3"],1,"var",varset([function(){var q=mcq("In the diagram below, which layer represents Earth's outer core?","C",["A","B","D"],"Reading from the surface inward, the labels are A the crust, B the mantle, C the outer core and D the inner core, so the outer core is C.",{});q.figure="<img src=\"banks/earth-3209/assets/u1-13-jun07-08.png\" alt=\"Cross-section diagram of Earth's interior with four labelled regions: A the crust, B the mantle, C the outer core and D the inner core at the centre.\">";return q;}]),["The outer core is the ring immediately around the centre."]);

// Source: June 2008 public exam, item 8.
E("es-u1-13-q04",1,["EA12.1.3"],1,"var",varset([function(){return mcq("Which of Earth's layers is thinnest?","crust",["inner core","lithosphere","mantle"],"The crust is Earth's thinnest layer: about 5 km thick under the oceans and 30 to 40 km thick under the continents, a small fraction of the roughly 100 km lithosphere and of the mantle below it.",{});}]),["It is the layer we live on."]);

// Source: June 2008 public exam, item 34.
E("es-u1-13-q05",1,["EA12.1.3"],1,"var",varset([function(){return mcq("Which layer of Earth is composed of solid iron and nickel?","inner core",["crust","mantle","outer core"],"The inner core is composed of solid iron and nickel; the outer core has the same composition but is liquid, melted by the same heat and kept liquid at lower pressure.",{});}]),["Pressure at the centre keeps it solid despite the heat."]);

// Source: June 2009 public exam, item 12.
E("es-u1-13-q06",1,["EA12.1.3"],2,"var",varset([function(){return mcq("Which is the most accurate statement about Earth's interior?","pressure within the mantle increases with depth",["mantle is molten rock","outer core is under the greatest pressure","temperature decreases toward Earth's centre"],"Pressure, density and temperature all increase with depth inside Earth, so pressure within the mantle increases with depth. The mantle is solid (though it can flow slowly), the greatest pressure is at the centre in the inner core, and temperature rises toward the centre.",{});}]),["Consider how each property changes as depth increases."]);

// Source: June 2009 public exam, item 36.
E("es-u1-13-q07",1,["EA12.1.3"],1,"var",varset([function(){return mcq("What is the name of the boundary between the mantle and crust?","Mohorovicic Discontinuity",["Gutenberg Discontinuity","Lehman Discontinuity","Repetti Discontinuity"],"The boundary between the crust and the mantle is the Mohorovicic Discontinuity, or Moho, recognized by the sudden increase in seismic wave velocity where the denser mantle begins.",{});}]),["It is usually shortened to the Moho."]);

// Source: June 2009 public exam, item 42.
E("es-u1-13-q08",1,["EA12.1.3"],2,"var",varset([function(){return mcq("Seismic evidence supporting the idea that a portion of Earth's core is liquid, is the observation that which type of waves will not pass through the core?","secondary",["long","primary","tsunami"],"Secondary (S) waves cannot travel through liquid, and they do not pass through the core; their absence beyond the core is the evidence that the outer core is liquid. Primary (P) waves are slowed and bent there but do get through.",{});}]),["One wave type is stopped by liquid."]);

// Source: August 2006 public exam, item 9.
E("es-u1-13-q09",1,["EA12.1.3"],1,"var",varset([function(){return mcq("Which layer of Earth is relatively weak and flows like plastic?","asthenosphere",["crust","inner core","lower mantle"],"The asthenosphere, the upper part of the mantle, is relatively weak and flows like plastic over geologic time, which is what allows the rigid plates above it to move.",{});}]),["It is the layer the plates rest on."]);

// Source: August 2006 public exam, item 10.
E("es-u1-13-q10",1,["EA12.1.3"],1,"var",varset([function(){var q=mcq("Which layer of Earth's interior shown below consists of molten nickel and iron?","C",["A","B","D"],"On the diagram, A is the crust, B the mantle, C the outer core and D the inner core. The outer core, C, is the layer of molten (liquid) nickel and iron.",{});q.figure="<img src=\"banks/earth-3209/assets/u1-13-aug06-10.png\" alt=\"Quarter cross-section diagram of Earth's interior with four labelled bands: A the thin crust at the outside, B the mantle, C the outer core and D the inner core at the centre.\">";return q;}]),["Molten means liquid; only one core layer is liquid."]);

// Source: August 2007 public exam, item 7.
E("es-u1-13-q11",1,["EA12.1.3"],2,"var",varset([function(){var q=mcq("Which layers of Earth have fluid properties?","B and C",["A and C","A and D","B and D"],"B is the mantle, which is solid but flows slowly (its asthenosphere behaves like plastic), and C is the outer core, which is liquid; both have fluid properties. A, the crust, and D, the inner core, are rigid solids.",{});q.figure="<img src=\"banks/earth-3209/assets/u1-13-aug07-07.png\" alt=\"Cross-section diagram of Earth's interior with four labelled regions: A the crust, B the mantle, C the outer core and D the inner core at the centre.\">";return q;}]),["One is a true liquid; the other is a solid that can flow."]);

// Source: August 2008 public exam, item 7.
E("es-u1-13-q12",1,["EA12.1.3"],2,"var",varset([function(){return mcq("Which best describes continental crust?","35-40 kilometres thick; lower density than ocean crust",["7 kilometres thick; higher density than ocean crust","7 kilometres thick; lower density than ocean crust","35-40 kilometres thick; higher density than ocean crust"],"Continental crust is thick (about 35 to 40 km) but made of lower-density rock, while oceanic crust is thin (about 5 to 7 km) and denser. The thickness figures rule out the 7 km options, and the density comparison rules out the remaining one.",{});}]),["Compare both the thickness and the density."]);

// Source: August 2008 public exam, item 8.
E("es-u1-13-q13",1,["EA12.1.3"],1,"var",varset([function(){return mcq("Which is the correct sequence of Earth's layers from the surface to the center?","crust - mantle - outer core - inner core",["crust - inner core - outer core - mantle","mantle - crust - inner core - outer core","mantle - outer core - inner core - crust"],"From the surface to the center, Earth's layers are the crust, the mantle, the outer core and the inner core.",{});}]),["Start at the surface and work inward."]);

// EA12.1.4 Identify that Earth is a dynamic planet
// Source: June 2006 public exam, item 56.
E("es-u1-14-q01",1,["EA12.1.4"],2,"var",varset([function(){return mcq("Which best compares oxygen concentration in Earth's atmosphere over time?","low in the Precambrian and high in the Cenozoic",["high in the Precambrian and high in the Cenozoic","high in the Precambrian and low in the Cenozoic","low in the Precambrian and low in the Cenozoic"],"Earth's atmosphere has changed over geologic time: oxygen was scarce through the long Precambrian, then built up as photosynthetic life spread, reaching high levels by the Cenozoic. A planet whose air itself changes is a dynamic, evolving planet. (The paper's two-column table options are rendered here as text.)",{});}]),["Free oxygen only appeared after photosynthetic life evolved."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.1.4.
E("es-u1-14-q02",1,["EA12.1.4"],1,"var",varset([function(){return mcq("Which statement best describes Earth as a dynamic planet?","Earth is constantly changing, at times slowly and at other times very rapidly",["Earth's surface features have remained unchanged for billions of years","Earth changes only during rare catastrophic events","Earth's interior is completely solid and inactive"],"Earth is an evolving planet: many processes are at work in its evolution, changing it slowly over millions of years and at other times rapidly, through events such as earthquakes, volcanoes and landslides.",{});}]),["Dynamic means ever changing."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.1.4.
E("es-u1-14-q03",1,["EA12.1.4"],2,"var",varset([function(){return mcq("Which pair of changes best shows that Earth changes at very different rates?","a mountain range rising over millions of years; a landslide burying a road in minutes",["a volcano erupting in a single day; an earthquake striking without warning","continents drifting centimetres per year; a glacier advancing metres per year","sediment settling on a lake bottom; a delta growing at a river mouth"],"The first pair spans the full range of rates: mountain building driven by plate movement takes millions of years, while a landslide reshapes a slope in minutes. Each other pair groups two changes that happen at similar rates, both fast or both slow.",{});}]),["Look for one very slow change paired with one very fast one."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.1.4.
E("es-u1-14-q04",1,["EA12.1.4"],2,"var",varset([function(){return mcq("The slow movement of Earth's crustal plates is directly responsible for which set of changes?","earthquakes, volcanic eruptions and the building of mountain ranges",["the daily tides, ocean currents and the water cycle","the seasons, the phases of the moon and eclipses","weathering of rock, soil formation and erosion by rivers"],"Where crustal plates meet, their movement produces earthquakes and volcanic eruptions and crumples rock into mountain ranges; these plate-driven changes are the clearest evidence that Earth is a dynamic planet.",{});}]),["The guide connects plate movement to processes at plate boundaries."]);

// EA12.1.5 Recognize that Earth processes operate within spheres
// Source: June 2006 public exam, item 10.
E("es-u1-15-q01",1,["EA12.1.5"],1,"var",varset([function(){return mcq("Which explains the origin of the hydrosphere?","volcanic outgassing",["comet impact","glacial melting","meteorite impact"],"Water vapour was among the gases released from Earth's interior by volcanic outgassing; as Earth cooled, the vapour condensed and collected to form the hydrosphere.",{});}]),["The same process also produced the atmosphere."]);

// Source: June 2007 public exam, item 7.
E("es-u1-15-q02",1,["EA12.1.5"],1,"var",varset([function(){return mcq("Which sphere includes groundwater?","hydrosphere",["atmosphere","biosphere","lithosphere"],"The hydrosphere includes all of Earth's water, surface and subsurface, so groundwater stored in rock and soil below the surface belongs to it.",{});}]),["Groundwater is still water."]);

// Source: June 2008 public exam, item 9.
E("es-u1-15-q03",1,["EA12.1.5"],1,"var",varset([function(){return mcq("Which formed as a result of volcanic outgassing?","the atmosphere and hydrosphere",["the biosphere and hydrosphere","the biosphere and lithosphere","the lithosphere and atmosphere"],"Volcanic outgassing released the gases that became the atmosphere and the water vapour that condensed to become the hydrosphere; the lithosphere had already formed by segregation, and life (the biosphere) came much later.",{});}]),["Outgassing supplied gases and water vapour."]);

// Source: June 2009 public exam, item 7.
E("es-u1-15-q04",1,["EA12.1.5","EA12.5.6"],2,"var",varset([function(){return mcq("Which spheres are interacting when a green plant absorbs carbon dioxide for photosynthesis?","atmosphere and biosphere",["atmosphere and geosphere","biosphere and hydrosphere","geosphere and hydrosphere"],"The carbon dioxide comes from the atmosphere, and the plant is part of the biosphere, so photosynthesis is an interaction between the atmosphere and the biosphere.",{});}]),["Name the sphere the gas comes from and the sphere the plant belongs to."]);

// Source: June 2009 public exam, item 9.
E("es-u1-15-q05",1,["EA12.1.5"],1,"var",varset([function(){return mcq("Which is the largest reservoir of fresh water on Earth?","glaciers",["groundwater","oceans","rivers"],"Most of Earth's fresh water is locked up in glaciers and ice caps, more than in groundwater, lakes and rivers combined. The oceans hold far more water overall, but it is salt water.",{});}]),["The question asks about fresh water, not all water."]);

// Source: June 2009 public exam, item 57.
E("es-u1-15-q06",1,["EA12.1.5"],2,"var",varset([function(){return mcq("Which gas in our atmosphere increased as a result of the evolution of plant life on Earth?","oxygen",["argon","carbon dioxide","sulfur dioxide"],"Photosynthesis by plant life releases oxygen, and as plants spread, oxygen built up in the atmosphere over geologic time; the early atmosphere had contained almost none.",{});}]),["Photosynthesis takes in one gas and releases another."]);

// Source: August 2006 public exam, item 7.
E("es-u1-15-q07",1,["EA12.1.5"],1,"var",varset([function(){return mcq("Which sphere of Earth contains all life?","biosphere",["atmosphere","geosphere","hydrosphere"],"The biosphere is the sphere of life, extending through parts of the atmosphere, hydrosphere and geosphere wherever organisms live.",{});}]),["The prefix bio- means life."]);

// Source: August 2008 public exam, item 57.
E("es-u1-15-q08",1,["EA12.1.5","EA12.5.6"],2,"var",varset([function(){return mcq("Which process shows a direct link between the atmosphere and the geosphere?","volcanic outgassing",["ground water pollution","ozone depletion","photosynthesis"],"In volcanic outgassing, gases from the geosphere (Earth's interior and its volcanoes) pass directly into the atmosphere; it is the process that built the atmosphere in the first place.",{});}]),["One process moves material from solid Earth into the air."]);

// Source: August 2009 public exam, item 3.
E("es-u1-15-q09",1,["EA12.1.5"],2,"var",varset([function(){return mcq("Based on the Solar Nebular Hypothesis, which occurred first?","geosphere",["atmosphere","biosphere","hydrosphere"],"The spheres formed in order: the geosphere first, as the solid Earth accreted and segregated, then the atmosphere from outgassing, then the hydrosphere as water vapour condensed, and the biosphere last of all.",{});}]),["The solid Earth had to exist before it could release gases."]);

// Source: August 2009 public exam, item 7.
E("es-u1-15-q10",1,["EA12.1.5"],1,"var",varset([function(){return mcq("Which of Earth's spheres includes rocks and minerals?","geosphere",["atmosphere","biosphere","hydrosphere"],"The geosphere is the solid Earth, from the core to the surface, so rocks and minerals belong to it.",{});}]),["The prefix geo- refers to the solid Earth."]);

// Source: Sample final exam, item 4.
E("es-u1-15-q11",1,["EA12.1.5"],1,"var",varset([function(){return mcq("Which represents the entire Earth from the core to the surface?","geosphere",["asthenosphere","crust","mantle"],"The geosphere is the entire solid Earth from the core to the surface; the crust, mantle and asthenosphere are each only one part of it.",{});}]),["One option names the whole solid Earth, not a layer of it."]);

// Source: Authored for this bank from the curriculum guide's elaboration of EA12.1.5, which uses a volcanic eruption as its example of spheres interacting.
E("es-u1-15-q12",1,["EA12.1.5","EA12.5.6"],3,"var",varset([function(){return mcq("A volcanic eruption pours lava over farmland, releases gases and ash that dim sunlight for weeks, and sends ash-laden runoff into a nearby river. Which statement correctly identifies the interactions?","The geosphere interacts with the atmosphere, the biosphere and the hydrosphere.",["The hydrosphere interacts with the geosphere, the biosphere and the atmosphere.","The atmosphere interacts with the geosphere, the hydrosphere and the biosphere.","The biosphere interacts with the atmosphere, the geosphere and the hydrosphere."],"The eruption originates in the geosphere. Its gases and ash enter the atmosphere, its lava destroys living farmland in the biosphere, and its runoff enters the river in the hydrosphere, so one geosphere event interacts with all three other spheres.",{});}]),["Start from the sphere where the event begins."]);

// Constructed response. Official items carry their grading-standard schemes.
// EA12.1.1
// Source: June 2008 public exam, item 62(a), 2 marks; marking points from the official grading standards.
E("es-u1-cr-q01",1,["EA12.1.1"],2,"var",varset([function(){return textq("Briefly describe the evolution of our solar system according to the solar nebular hypothesis.",["a rotating cloud of gas and dust contracts under gravity","the material flattens into a disk as rotation speeds up","a protosun forms at the centre and proto-planets form in the disk","remaining dust and gases are swept away by solar winds"],"<b>Model answer:</b> A huge rotating cloud of dust and gases began to contract under gravity toward its centre. As the material contracted it rotated faster and faster, which flattened it into a disk shape. Material concentrated in the centre formed the protosun, which eventually became the sun, while the remaining material in the flattened disk accreted to form the planets. In time, most of the remaining debris was added to the planets or swept out into space by solar winds.<br><br><b>Marking points (2 marks):</b> 0.5 mark for the rotating mass of gases contracting under gravity; 0.5 mark for the material flattening into a disk; 0.5 mark for the protosun forming at the centre and proto-planets forming in the disk; 0.5 mark for the remaining dust and gases being swept away by solar winds.",{});}]),["Name the four stages in order."]);

// Source: August 2006 public exam, item 61(a), 2 marks; model answer from the official grading standards.
E("es-u1-cr-q02",1,["EA12.1.1"],2,"var",varset([function(){return textq("The Orion nebula is a cloud of dust and gas in space. Explain how this nebula could form a solar system similar to the one in which we live.",["the cloud contracts toward its centre and rotates faster","the material flattens into a disk with a protosun at its centre","the remaining material in the disk accretes to form planets"],"<b>Model answer:</b> The nebular hypothesis explains how such a cloud forms a solar system. The huge rotating cloud of dust and gases begins to contract toward its centre; as it contracts it rotates faster and faster, flattening into a disk. The material concentrated in the centre forms a protosun, which eventually becomes a sun. The remaining material within the flattened disk accretes to form planets, and in time most leftover debris is added to the planets or swept out into space by solar winds.<br><br><b>Marking points (2 marks):</b> award the 2 marks across that sequence, contraction and faster rotation, flattening into a disk, protosun at the centre, and accretion of the remaining material into planets.",{});}]),["Apply the nebular hypothesis stage by stage."]);

// EA12.6.2
// Source: Authored for this bank from the Woodland workbook, Unit 1, Lesson 1, definitions and the curriculum guide's STSE component for EA12.6.2.
E("es-u1-cr-q03",1,["EA12.6.2"],2,"var",varset([function(){return textq("Explain how a hypothesis can develop into a theory, and describe what could cause an accepted theory to be replaced by a new paradigm.",["a hypothesis that survives extensive testing, with competing hypotheses eliminated, becomes a theory","accumulated evidence that a theory cannot explain can force its replacement by a new paradigm"],"<b>Model answer:</b> A hypothesis is a preliminary, untested explanation of an observation. If it goes through extensive testing and scrutiny and the competing hypotheses are eliminated, it can be accepted as a scientific theory, an explanation that accounts for the observed facts. A theory is still tested against new evidence as it is gathered; if evidence accumulates that the theory cannot explain, scientists revise it, and when the replacement is fundamentally different the change is a new paradigm, as when plate tectonics replaced continental drift.<br><br><b>Marking points (2 marks):</b> 1 mark for the testing path from hypothesis to theory; 1 mark for replacement driven by evidence the accepted theory cannot explain.",{});}]),["Use the workbook definitions of hypothesis and theory."]);

// EA12.1.2
// Source: August 2007 public exam, item 62(b), 2 marks; model answer from the official grading standards.
E("es-u1-cr-q04",1,["EA12.1.2"],2,"var",varset([function(){return textq("Explain the importance of radioactive decay and gravitational forces in the segregation of Earth's interior.",["radioactive decay helped generate the heat that melted Earth's interior","gravitational forces separated the molten material by density"],"<b>Model answer:</b> Billions of years ago, the decay of radioactive elements, together with heat generated by colliding particles, caused Earth's interior to melt. Melting allowed the interior to segregate: gravitational forces separated the material based on density, so the denser elements, nickel and iron, sank toward the centre while the lighter rocky components (silicates) floated toward the surface. This segregation by density produced Earth's layered interior.<br><br><b>Marking points (2 marks):</b> award the 2 marks across the two roles, radioactive decay as a heat source that melted the interior, and gravity as the force that sorted the molten material by density.",{});}]),["One source supplied the heat; the other did the sorting."]);

// Source: August 2008 public exam, item 62(b), 2 marks; model answer from the official grading standards.
E("es-u1-cr-q05",1,["EA12.1.2"],2,"var",varset([function(){return textq("Describe the process that could lead to the segregation of layers within a newly-formed planet.",["impacts and radioactive decay heat the planet's interior until it melts","gravity then sorts the molten material by density into layers"],"<b>Model answer:</b> A newly-formed planet has a homogeneous solid interior, the same throughout. Impacts from meteoroids and asteroids make its particles collide and heat up through friction, and heat also builds as radioactive elements in the rock decay. The accumulated heat eventually melts the interior. Once molten, the heavier, denser elements move toward the centre and the lighter, less dense elements move toward the surface, and over an extended period the planet becomes segregated into layers according to density.<br><br><b>Marking points (2 marks):</b> award the 2 marks across the heating and melting of the interior and the density sorting by gravity that follows.",{});}]),["Start with a planet that is the same throughout."]);

// Source: June 2009 public exam, item 62(a), 2 marks; marking points from the official grading standards.
E("es-u1-cr-q06",1,["EA12.1.2"],3,"var",varset([function(){return textq("There is no evidence to suggest that Pluto ever melted. How would its interior structure differ from that of Earth?",["without melting, segregation (differentiation) could not occur","no distinct layers could form; the interior stays an unorganized solid mass"],"<b>Model answer:</b> Earth's layers exist because its interior melted (heated by radioactive decay, accretion and gravitational forces) and then segregated: high-density materials sank toward the centre and low-density materials rose toward the surface. With no melting on Pluto, segregation could not take place, so distinct layers could not form; Pluto's interior would remain a large, solid, unorganized mass of mixed elements and minerals rather than a layered structure.<br><br><b>Marking points (2 marks):</b> 1 mark for indicating that segregation was unable to occur because there was no melting (no sufficient sources of heat); 1 mark for indicating that distinct layers could not form without segregation.",{});}]),["No melting means no segregation."]);

// Source: Sample final exam, item 76, 2 marks; marking points from the official answer key.
E("es-u1-cr-q07",1,["EA12.1.2"],3,"var",varset([function(){return textq("Based on the information below, answer the question that follows. A recently discovered planet in our solar system has been found to be a mass of entirely solid rock. Several large deposits of pure nickel and iron were found near the surface. Advanced seismic records showed that there are several large regions of silicate minerals at depth. How does this planet differ in structure from present day Earth? Explain a process that must occur for this planet to acquire Earth's structure.",["unlike Earth, the planet never underwent segregation","its interior would have to melt so that gravity could sort its materials by density"],"<b>Model answer:</b> Unlike Earth, this planet did not experience segregation. The evidence is the unsorted distribution of its materials: high-density nickel and iron sit near the surface and low-density silicate minerals lie at depth, the reverse of Earth, and the planet is one solid mass rather than Earth's structure of solid, liquid and plastic-like layers. For the planet to acquire Earth's structure, its interior would have to melt (through heat from impacts and radioactive decay) so that gravity could segregate the material by density, sinking the nickel and iron to form a core and floating the silicates upward.<br><br><b>Marking points (2 marks):</b> 1 mark for indicating that, unlike Earth, the planet did not experience segregation; 1 mark for the supporting evidence (dense materials near the surface, light materials at depth, no layered states) and the melting that segregation requires. (House fix: the sample final printed 'nickle'; the standard spelling is 'nickel'.)",{});}]),["Compare where the planet's materials sit with where Earth's sit."]);

// EA12.1.4
// Source: Authored for this bank from the curriculum guide's elaboration of EA12.1.4.
E("es-u1-cr-q08",1,["EA12.1.4"],2,"var",varset([function(){return textq("Earth is described as a dynamic planet. Describe one change to Earth's surface that happens very slowly and one change that happens rapidly, naming the process responsible for each.",["slow change: crustal plate movement raising a mountain range over millions of years","rapid change: an earthquake, volcanic eruption or landslide changing the surface in minutes to days"],"<b>Model answer:</b> Slow change: the movement of crustal plates crumples rock layers upward a few centimetres a year, raising a mountain range over millions of years. Rapid change: a volcanic eruption can bury a landscape under lava and ash in a single day (an earthquake or a landslide likewise changes the surface in minutes).<br><br><b>Marking points (2 marks):</b> 1 mark for a slow change with its process (plate movement, mountain building, continental drift or long-term erosion); 1 mark for a rapid change with its process (earthquake, volcanic eruption or landslide).",{});}]),["Think in millions of years, then in minutes."]);

// EA12.1.5
// Source: June 2006 public exam, item 62(a), 2 marks; marking points from the official grading standards.
E("es-u1-cr-q09",1,["EA12.1.5"],2,"var",varset([function(){return textq("If volcanic activity had never taken place on Earth, explain what effect this would have had in relation to the origin of the atmosphere and hydrosphere.",["no atmosphere would have been created","no hydrosphere would have been created"],"<b>Model answer:</b> Earth's atmosphere and hydrosphere originated from gases released through volcanic activity (outgassing) billions of years ago: the gases formed the atmosphere, and water vapour among them later condensed to form the oceans. If volcanic activity had never taken place, those gases would never have been released, so neither the atmosphere nor the hydrosphere would have formed.<br><br><b>Marking points (2 marks):</b> 1 mark for stating no atmosphere would have been created; 1 mark for stating no hydrosphere would have been created.",{});}]),["Where did the gases and the water vapour come from originally?"]);

// Source: August 2008 public exam, item 62(a), 2 marks; model answer from the official grading standards.
E("es-u1-cr-q10",1,["EA12.1.5","EA12.5.6"],2,"var",varset([function(){return textq("Explain how the interaction between the hydrosphere and lithosphere influences landscapes.",["moving water and ice weather and erode the lithosphere","this erosion shapes landscape features such as valleys, cirques and sea stacks"],"<b>Model answer:</b> The hydrosphere is Earth's water in both liquid and solid (ice) states, and the lithosphere is the solid upper 100 km of Earth. As ice (glaciers) and moving water (rivers, groundwater, waves) move over and through the lithosphere, they weather and erode it, and the erosive forces shape the surface into landscape features such as glacial valleys, cirques, eskers, river valleys and sea stacks.<br><br><b>Marking points (2 marks):</b> award the 2 marks across the erosive action of water and ice on the lithosphere and the landscape features that result, with credit for apt examples.",{});}]),["Which agent does the shaping, and what does it shape?"]);

