/* ----- EA12.2.1: Define uniformitarianism ----- */
E("es-u2-21-q01",2,["EA12.2.1"],1,"var",varset([function(){return mcq("Which statement best defines uniformitarianism?","The geologic processes that operate today also operated in the past, at broadly similar rates.",["Earth's surface features were shaped mainly by sudden, catastrophic events.","Sedimentary rock layers are always deposited in flat, horizontal layers.","A fossil is the preserved remains or traces of an organism that lived long ago."],"Uniformitarianism holds that the processes shaping Earth today, such as erosion, deposition and volcanism, are the same processes that shaped it in the past. The other statements define catastrophism, original horizontality and a fossil.",{});}]),["Think: the present is the key to the past."]);

/* ----- EA12.2.2: Distinguish between absolute and relative time ----- */
E("es-u2-22-q01",2,["EA12.2.2"],1,"var",varset([function(){return mcq("Which statement best represents how relative time is correctly used in Earth Science?","Dykes and sills are younger than surrounding rock.",["Dinosaurs became extinct 65 million years ago.","The rock is 500 million years old.","The rock unit above is older than the rock unit below."],"Relative time places events in order without giving a numerical age. A dyke or sill is younger than the rock it cuts, which is a relative statement; the other choices either give numerical ages or reverse the order.",{});}]),["Relative time orders events; it does not number them."]);
E("es-u2-22-q02",2,["EA12.2.2"],1,"var",varset([function(){return mcq("Which provides an example of relative time?","comparing positions of layers in a sedimentary sequence",["comparing ratios between parent and daughter isotopes","counting tree rings","counting varves"],"Comparing the positions of layers orders them as older or younger without a numerical age, which is relative time. Isotope ratios, tree rings and varves all yield numerical ages, which is absolute time.",{});}]),["Which method orders events instead of numbering them?"]);

/* ----- EA12.2.3: Principles and laws used to establish relative time ----- */
E("es-u2-23-q01",2,["EA12.2.3"],1,"var",varset([function(){return mcq("Which best illustrates the concept that sediment is deposited in flat layers?","horizontality",["correlation","superposition","uniformitarianism"],"Sediment settles out in flat, horizontal layers, the principle of original horizontality. Tilted or folded layers must have been disturbed after they were deposited.",{});}]),["The principle is named for the way the layers start out."]);
E("es-u2-23-q02",2,["EA12.2.3"],1,"var",varset([function(){return mcq("Which geologic principle states that in an undisturbed sedimentary sequence, the bottom layer is oldest?","superposition",["correlation","horizontality","uniformitarianism"],"The principle of superposition: in an undisturbed sequence, each layer is older than the one above it and younger than the one below it.",{});}]),["It is the layer-ordering principle."]);
E("es-u2-23-q03",2,["EA12.2.3"],2,"var",varset([function(){return mcq("A geologist found four sedimentary beds, conglomerate, sandstone, siltstone, and shale, laid down one on top of the other (conglomerate on bottom, shale on top). The geologist concluded that the conglomerate bed was oldest since it was found on the bottom. Which geological principle was used to arrive at this conclusion?","superposition",["cross-cutting relationships","fossil correlation","uniformitarianism"],"The conclusion rests on layer position alone: in an undisturbed sequence the bottom layer is the oldest, which is the principle of superposition.",{});}]),["The reasoning uses nothing but the order of the beds."]);
E("es-u2-23-q04",2,["EA12.2.3"],2,"var",varset([function(){var q=mcq("What principle tells us that the fossil brachiopod is older than the fossil gastropod in the rock section below?","superposition",["catastrophism","correlation","uniformitarianism"],"The brachiopod layer lies below the gastropod layer in an undisturbed section, so by superposition it was deposited first and is older.",{});q.figure='<img src="banks/earth-3209/assets/u2-23-jun09-04.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Compare the depths of the two fossil layers."]);
E("es-u2-23-q05",2,["EA12.2.3"],2,"var",varset([function(){var q=mcq("Which geological principle is used to determine that layer X is older than layer W?","relative dating",["absolute time","cross cutting relationships","fossil succession"],"Layer X lies below layer W, so superposition places it first. Relative dating is the method that orders events in sequence without assigning numerical ages. No feature cuts across the layers, and no fossils are shown.",{});q.figure='<img src="banks/earth-3209/assets/u2-23-jun08-06.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["X sits below W in the sequence."]);
E("es-u2-23-q06",2,["EA12.2.3"],2,"var",varset([function(){var q=mcq("Which letter in the diagram indicates cross-cutting?","C",["A","B","D"],"The leader line from C points to the dyke that slices across the folded layers of the block. A feature that cuts across other rocks is younger than everything it cuts.",{});q.figure='<img src="banks/earth-3209/assets/u2-23-jun07-48.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Follow each leader line to the feature it touches."]);
E("es-u2-23-q07",2,["EA12.2.3"],2,"var",varset([function(){var q=mcq("Which geologic structure is indicated by the arrow below?","angular unconformity",["conformity","disconformity","nonconformity"],"The arrow points to the erosion surface where flat-lying beds rest on tilted beds below. An erosion surface between tilted older strata and flat younger strata is an angular unconformity.",{});q.figure='<img src="banks/earth-3209/assets/u2-23-jun06-48.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Compare the tilt of the beds above and below the arrow."]);
E("es-u2-23-q08",2,["EA12.2.3"],2,"var",varset([function(){var q=mcq("Which unconformity is identified by X in the diagram below?","angular",["disconformity","inclusions","nonconformity"],"X marks the bold erosion surface: the strata beneath it are tilted, while the beds above it lie flat. That angular relationship makes it an angular unconformity.",{});q.figure='<img src="banks/earth-3209/assets/u2-23-aug07-41.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Look at the angle between the rocks below X and the beds above it."]);
E("es-u2-23-q09",2,["EA12.2.3"],2,"var",varset([function(){var q=mcq("What type of boundary exists at Z in the diagram below?","angular unconformity",["bedding plane","intrusion","nonconformity"],"Z points to the wavy erosion surface at the top of the tilted layers, with flat-lying beds above it. Tilted strata truncated by erosion and buried by flat strata mark an angular unconformity.",{});q.figure='<img src="banks/earth-3209/assets/u2-23-aug08-45.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["The surface at Z separates tilted rock below from flat rock above."]);
E("es-u2-23-q10",2,["EA12.2.3"],1,"var",varset([function(){var q=mcq("Which feature is shown in the diagram below?","unconformity",["correlation","inclusions","metamorphism"],"The diagram shows an erosion surface (the heavy wavy line) between tilted older layers below and younger layers above: a break in the rock record, which is an unconformity.",{});q.figure='<img src="banks/earth-3209/assets/u2-23-final-08.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["The heavy wavy line is a gap in the record."]);

/* ----- EA12.2.4: Construct and interpret cross-sectional diagrams ----- */
E("es-u2-24-q01",2,["EA12.2.4"],3,"var",varset([function(){var q=mcq("Which sequence, from oldest to youngest, is correct for the geologic cross-section below?","C, F, B, Z, X, E, D, Y",["C, F, B, X, Z, E, D, Y","Y, D, E, X, Z, B, F, C","Y, E, D, Z, X, B, F, C"],"By superposition the lower tilted units (C, then F, then B) are oldest. The fault Z cuts them, the erosion surface X truncates both, E was deposited on X, the dyke D cuts everything below the top surface, and the surface deposit Y is youngest. (House fix: the sample final printed the first option with a missing comma before Y.)",{});q.figure='<img src="banks/earth-3209/assets/u2-24-final-07.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Build the order from the bottom up, then place the fault, the erosion surface and the dyke."]);
E("es-u2-24-q02",2,["EA12.2.4"],3,"var",varset([function(){var q=mcq("Which is correct regarding the cross-section below?","B is the youngest rock in the cross-section",["C has folding at its base","E was faulted after the formation of A","D is the result of tensional forces"],"The dyke B cuts across every other unit in the section, including the uppermost beds, so by cross-cutting relationships it is the youngest rock present. The base of C is the erosion surface A, not a fold, and the fault is truncated by A, so faulting came before A formed.",{});q.figure='<img src="banks/earth-3209/assets/u2-24-jun07-49.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Test each statement against superposition and cross-cutting."]);
E("es-u2-24-q03",2,["EA12.2.4"],3,"var",varset([function(){var q=mcq("If letters A through G represent rock layers in the diagram below, which sequence of geological events caused the unconformity indicated by letter H?","folding, uplift, erosion, deposition",["deposition, uplift, erosion, folding","erosion, folding, deposition, intrusion","intrusion, erosion, folding, uplift"],"The layers below H were deposited flat, then folded, then uplifted and eroded to produce the wavy surface H; flat layers F and G were deposited on that surface afterward. The event order that built the unconformity is folding, uplift, erosion, then renewed deposition.",{});q.figure='<img src="banks/earth-3209/assets/u2-24-aug09-42.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Work out what had to happen to the lower layers before the flat layers could rest on them."]);
E("es-u2-24-q04",2,["EA12.2.4"],3,"var",varset([function(){var q=mcq("Which sequence of events, from oldest to youngest, is correct for the cross-section below?","deposition of the tilted layers, faulting, erosion (surface A), deposition of layer C, intrusion of dyke B",["deposition of the tilted layers, erosion (surface A), faulting, deposition of layer C, intrusion of dyke B","intrusion of dyke B, deposition of the tilted layers, faulting, erosion (surface A), deposition of layer C","deposition of the tilted layers, faulting, deposition of layer C, erosion (surface A), intrusion of dyke B"],"The tilted layers were deposited first, then faulted. The erosion surface A truncates both the tilted layers and the fault, so erosion followed faulting. Layer C and the beds above it were deposited on A, and the dyke B cuts every unit, so it came last.",{});q.figure='<img src="banks/earth-3209/assets/u2-24-jun07-49.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["The erosion surface A cuts the fault off; the dyke cuts everything."]);

/* ----- EA12.2.5: Theories and limits of our understanding of Earth's internal structure ----- */
E("es-u2-25-q01",2,["EA12.2.5"],1,"var",varset([function(){return mcq("Which scientific device provided data to support the outer core being a liquid?","seismograph",["magnetometer","microscope","telescope"],"A seismograph records earthquake waves. S-waves cannot travel through liquid and are stopped at the outer core, while P-waves are refracted there, which is the evidence that the outer core is liquid.",{});}]),["It records earthquake waves."]);
E("es-u2-25-q02",2,["EA12.2.5"],2,"var",varset([function(){return mcq("Which statement best describes a limit on our understanding of Earth's internal structure?","No borehole has penetrated beyond the crust, so the mantle and core can be studied only through indirect evidence such as seismic waves.",["Seismic waves are completely blocked by Earth's interior, so nothing is known below the crust.","The liquid outer core has been sampled directly by the deepest drill holes on Earth.","Earth's interior is fully understood because each layer has been observed in place."],"Even the deepest boreholes reach only a fraction of the crust. Everything known about the mantle and core comes from indirect evidence, mainly the behaviour of seismic waves, which is a real limit on the theories built from it.",{});}]),["Think about how far direct sampling actually reaches."]);

/* ----- EA12.2.6: Processes and features used to establish absolute time ----- */
E("es-u2-26-q01",2,["EA12.2.6"],2,"var",varset([function(){return mcq("A geologist discovered that a lake bed had 240 alternating light and dark layers. If each couplet represents a year of deposition, how long did it take for the entire lake bed to form?","120 years",["60 years","240 years","480 years"],"Each year adds one couplet, a light layer plus a dark layer, so 240 layers make 240 / 2 = 120 couplets, or 120 years. Layers laid down in this yearly pattern are called varves.",{});}]),["Count the light-and-dark pairs, not the single layers."]);
E("es-u2-26-q02",2,["EA12.2.6"],1,"var",varset([function(){return mcq("Which technique would be used to perform absolute dating of a tree that died 50 years ago?","counting growth rings",["comparing soil profiles","cross-cutting","superposition"],"A tree adds one growth ring per year, so counting rings gives a numerical age, which is absolute dating. Cross-cutting and superposition give relative order only.",{});}]),["Which method produces a number of years?"]);
E("es-u2-26-q03",2,["EA12.2.6"],2,"var",varset([function(){return mcq("Why can tree-ring patterns be used to determine the age of wooden beams in historic buildings?","Ring-width patterns from trees with overlapping lifespans can be matched against a master chronology extending back thousands of years.",["Counting the rings in a beam gives the year the building was built, because beams are always used the year they are cut.","The rings contain carbon-14, and its decay dates the wood directly without any pattern matching.","Ring patterns are identical in every tree, so a single ring can be matched to any calendar year."],"Trees in a region record the same pattern of wide and narrow rings in wet and dry years. Matching a beam's pattern against overlapping patterns from older and older wood (cross-dating) ties it to an exact span of calendar years.",{});}]),["The method matches patterns, not just counts."]);

/* ----- EA12.2.7: Explain how half-lives are used in estimating ages ----- */
E("es-u2-27-q01",2,["EA12.2.7"],1,"var",varset([function(){return mcq("The process by which atomic nuclei spontaneously break apart (decay) is termed","radioactivity",["fusion","ionization","reduction"],"Radioactive decay is the spontaneous breakdown of an unstable parent nucleus into a daughter product. Radiometric dating works because this breakdown happens at a constant, measurable rate.",{});}]),["It is the process behind radiometric dating."]);
E("es-u2-27-q02",2,["EA12.2.7"],2,"var",varset([function(){return mcq("A sample of a fossil is found to contain 1/8 the amount of carbon-14 that it originally contained. How old is this fossil? [Half-life = 5 730 years]","17 190 years",["716 years","5730 years","34 380 years"],"One-eighth remaining means 1/2 x 1/2 x 1/2, so 3 half-lives have passed. Age = 3 x 5,730 = 17,190 years.",{});}]),["1/8 = (1/2) cubed. How many halvings is that?"]);
E("es-u2-27-q03",2,["EA12.2.7"],2,"var",varset([function(){return mcq("If a mineral contained 100% C14, and the sample now contains 25% C14, how old is the sample? (C14 half-life = 5730 yrs)","11,460 years",["716 years","5,730 years","17,190 years"],"Falling from 100% to 25% is two halvings (100 to 50 to 25), so 2 half-lives have passed. Age = 2 x 5,730 = 11,460 years.",{});}]),["Count the halvings from 100% down to 25%."]);
E("es-u2-27-q04",2,["EA12.2.7"],2,"var",varset([function(){return mcq("If the half-life of potassium-40 is 1.3 billion years, how old is a rock in which only 1/8 of the original potassium-40 remains?","3.9 billion years",["1.3 billion years","2.6 billion years","5.2 billion years"],"One-eighth remaining means 3 half-lives have passed. Age = 3 x 1.3 billion = 3.9 billion years.",{});}]),["1/8 remaining means three halvings."]);
E("es-u2-27-q05",2,["EA12.2.7"],3,"var",varset([function(){return mcq("A rock was analyzed using U-235 which has a half-life of 713 million years. There is 25 g of the parent isotope and 175 g of the daughter product, lead-207, in the rock. How old is the sample?","2139 million years",["713 million years","1426 million years","2852 million years"],"The rock started with 25 + 175 = 200 g of parent. Halving: 200 to 100 to 50 to 25 g, so 3 half-lives have passed. Age = 3 x 713 million = 2139 million years.",{});}]),["Rebuild the original amount first: parent plus daughter."]);
E("es-u2-27-q06",2,["EA12.2.7"],2,"var",varset([function(){return mcq("A sample has 1/16 of its original radioactive parent isotope remaining. If the half-life of the isotope is 47,000 years, how old is the sample?","188,000 years",["47,000 years","94,000 years","141,000 years"],"One-sixteenth remaining means 4 half-lives have passed (1/2, 1/4, 1/8, 1/16). Age = 4 x 47,000 = 188,000 years. (Converted from a workbook Unit 2b question.)",{});}]),["Keep halving: 1/2, 1/4, 1/8, then 1/16."]);
E("es-u2-27-q07",2,["EA12.2.7"],2,"var",varset([function(){return mcq("During radioactive decay, what will be the parent/daughter ratio after three half-lives?","1:7",["1:3","1:5","1:6"],"After three half-lives the parent is 1/8 of the original amount and the daughter is 7/8, so the parent/daughter ratio is 1:7. (Converted from the Dr Dean Chapter 8 test.)",{});}]),["After three halvings, what fraction is still parent?"]);

/* ----- EA12.11.5: Evaluate the sources of error and limitations in estimating radiometric age ----- */
E("es-u2-115-q01",2,["EA12.11.5"],2,"var",varset([function(){return mcq("A sample of igneous rock is dated using radioactive decay. During metamorphism, the daughter isotope, which is a gas, is lost from the rock. Which problem will this cause in determining the age of the rock?","The calculated age will be younger than the actual age of the rock.",["The calculated age will be older than the actual age of the rock.","There will be no way to determine if the rock is young or old.","This will have no effect on the calculated age."],"Losing daughter product lowers the measured daughter-to-parent ratio, so fewer half-lives appear to have passed and the calculated age comes out younger than the true age.",{});}]),["Less daughter product looks like less decay has happened."]);
E("es-u2-115-q02",2,["EA12.11.5"],1,"var",varset([function(){return mcq("Which pair is correctly matched with regards to radioactive dating?","mummified human bones: carbon-14",["granite rock: carbon-14","Precambrian shield: potassium-argon","trilobite: uranium-lead"],"A mummy is young, once-living material, well inside carbon-14's useful range. Granite and Precambrian rocks are far too old for carbon-14, and trilobite fossils are dated by the rocks around them rather than by uranium-lead on the fossil itself.",{});}]),["Match the isotope's range to the material's age."]);
E("es-u2-115-q03",2,["EA12.11.5"],2,"var",varset([function(){return mcq("Why does radiometric dating rarely give the true depositional age of a sedimentary rock?","Its grains were weathered from older rocks, so the radioactive clocks record the age of the source rocks, not of the deposit.",["Sedimentary rocks contain no radioactive isotopes of any kind.","Radioactive isotopes decay much faster in sedimentary rocks than in igneous rocks.","Sedimentary rocks are all too young to hold measurable amounts of daughter isotope."],"The mineral grains in a sedimentary rock formed in older igneous or metamorphic source rocks, and their decay clocks started then. Dating the grains dates the source, so sedimentary layers are usually dated indirectly, using igneous intrusions and flows around them.",{});}]),["Ask when the grains' clocks actually started."]);

/* ----- EA12.7.3: Importance of communicating the results of a scientific endeavour ----- */
E("es-u2-73-q01",2,["EA12.7.3"],1,"var",varset([function(){return mcq("A student writes up the radiometric dating results for a zircon sample. Which practice best follows the conventions for communicating scientific results?","Reporting the parent and daughter isotopes measured, the calculated age with its units, and the method used.",["Describing the sample as very old so the result is easy for anyone to understand.","Omitting the measurement uncertainty so the reported age appears exact.","Reporting only the final age, rounded to the nearest single year."],"Communicating results properly means another scientist could evaluate or repeat the work: the isotopes, the method, the age with units, and the uncertainty all belong in the report.",{});}]),["Could another scientist check this result from the write-up alone?"]);
E("es-u2-73-q02",2,["EA12.7.3"],2,"var",varset([function(){return mcq("Zircon crystals from Labrador have been dated at about 3.9 billion years using uranium-lead dating. Which statement communicates this result with appropriate scientific language and conventions?","Uranium-238 in the zircons decays to lead-206 with a half-life of 4.5 billion years, and the measured parent-to-daughter ratio gives an age of about 3.9 billion years.",["Scientists feel the zircons formed 3.9 billion years ago, give or take a few years.","The zircons are 3.9 billion years old because they look extremely ancient.","The zircons are exactly 3,900,000,000 years old, the oldest age ever measured."],"The keyed statement names the parent and daughter isotopes, states the half-life, ties the age to the measured ratio, and keeps the word 'about', which respects the measurement's uncertainty. The distractors rely on appearance or opinion, or claim an exactness no measurement can support.",{});}]),["Look for isotopes, a half-life, and an honest 'about'."]);

/* ----- EA12.2.8: Describe how fossils are used to distinguish geologic time ----- */
E("es-u2-28-q01",2,["EA12.2.8"],2,"var",varset([function(){return mcq("Which process is best used to date a rock in one location so it can be compared to a rock in another location?","correlation",["carbonization","permineralization","replacement"],"Correlation matches rock units of the same age in different places, using fossils and rock characteristics. Carbonization, permineralization and replacement are ways fossils form, not ways of comparing locations.",{});}]),["It is the matching of same-aged rocks between places."]);
E("es-u2-28-q02",2,["EA12.2.8"],2,"var",varset([function(){var q=mcq("Which method was used to conclude that Units I and II represent the same time interval?","fossil correlation",["fossil displacement","fossil equilibrium","fossil succession"],"The two units contain matching sequences of the same fossil assemblages (A through F), so they are correlated as the same time interval by their fossils, which is fossil correlation.",{});q.figure='<img src="banks/earth-3209/assets/u2-28-jun09-52.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["The same fossil assemblages appear in both units."]);
E("es-u2-28-q03",2,["EA12.2.8"],2,"var",varset([function(){var q=mcq("In which diagram is the correct evolutionary sequence present?","B",["A","C","D"],"In column B the fossils appear in the accepted evolutionary order from bottom (oldest) to top (youngest): shell (invertebrate), trilobite, fish, frog (amphibian), then mammal. The other columns place at least one group out of order.",{});q.figure='<img src="banks/earth-3209/assets/u2-28-jun08-53.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Read each column from oldest (bottom) to youngest (top)."]);
E("es-u2-28-q04",2,["EA12.2.8"],1,"var",varset([function(){return mcq("Fossils that are widespread geographically and are limited to a short span of geologic time are referred to as which type of fossils?","index",["key","relative","succeeding"],"An index fossil comes from an organism that lived over a wide area but for only a short time, which pins its rock layer to a narrow time interval and makes it ideal for correlation. (Converted from the Dr Dean Chapter 8 test.)",{});}]),["Wide area, short time span."]);

/* ----- EA12.2.9: Define fossil ----- */
E("es-u2-29-q01",2,["EA12.2.9"],1,"var",varset([function(){return mcq("The remains or traces of prehistoric life are known as","fossils",["fissures","indicators","replicas"],"A fossil is the remains or traces of prehistoric (ancient) life preserved in rock. (Converted from the Dr Dean Chapter 8 test.)",{});}]),["Remains or traces, preserved from the distant past."]);
E("es-u2-29-q02",2,["EA12.2.9"],1,"var",varset([function(){return mcq("Which is a fossil?","The preserved shell of a marine animal in a limestone bed",["A footprint pressed into fresh snow yesterday","A quartz crystal that grew inside a granite","A seashell collected from a modern beach"],"A fossil is evidence of past life preserved from prehistoric time. A shell collected today, a fresh footprint and a crystal are not preserved remains or traces of prehistoric life.",{});}]),["It must be preserved evidence of prehistoric life."]);

/* ----- EA12.2.10: Describe three conditions necessary for fossilization ----- */
E("es-u2-210-q01",2,["EA12.2.10"],1,"var",varset([function(){return mcq("What factor contributes to an increased chance of fossilization for an organism?","presence of hard body parts",["absence of hard body parts","endothermic reactions","warm water currents"],"Hard parts such as shells, bones and teeth resist decay and scavenging long enough to be buried and preserved. Soft-bodied organisms fossilize only in exceptional conditions.",{});}]),["What survives long enough to be buried?"]);
E("es-u2-210-q02",2,["EA12.2.10"],1,"var",varset([function(){return mcq("Which factor contributes most to the fossilization of an animal?","Rapid burial of the remains.",["Bacteria present in the soil.","Exposure to wind and water.","Predatory animals nearby."],"Rapid burial seals the remains away from scavengers, bacteria and the weather, which is the single biggest factor in whether an animal is fossilized.",{});}]),["What protects the remains from decay and scavengers?"]);
E("es-u2-210-q03",2,["EA12.2.10"],2,"var",varset([function(){return mcq("A paleontologist searched for fossils in a rock unit. Which organism would most likely be found preserved in the rock unit?","bird",["flower","jellyfish","worms"],"The bird has hard parts (bones, beak) that resist decay, giving it the best chance of fossilization. The flower, jellyfish and worms are soft-bodied and decay quickly unless conditions are exceptional.",{});}]),["Which organism has preservable hard parts?"]);

/* ----- EA12.2.11: Describe the formation of various types of fossils ----- */
E("es-u2-211-q01",2,["EA12.2.11"],1,"var",varset([function(){return mcq("Which method of fossilization involves the replacement of the internal and external structures of hard parts by minerals, allowing for preservation of great detail?","replacement",["carbonization","distillation","pseudomorphism"],"In replacement, mineral matter substitutes for the original hard-part material cell by cell, preserving fine internal and external detail.",{});}]),["The original material is swapped for minerals."]);
E("es-u2-211-q02",2,["EA12.2.11"],1,"var",varset([function(){return mcq("Which would produce a trace fossil?","footprints and burrows",["body of an organism","foot bones","shell impressions"],"A trace fossil records an organism's activity rather than its body: footprints, burrows, trails and coprolites. Bones and shells are body fossils.",{});}]),["Trace fossils record behaviour, not body parts."]);
E("es-u2-211-q03",2,["EA12.2.11"],1,"var",varset([function(){var q=mcq("What type of fossil is illustrated in the diagram below?","trace",["body","carbon","cast"],"The diagram shows a footprint: evidence of an animal's activity, not a part of its body. Fossils of activity (footprints, burrows, trails) are trace fossils.",{});q.figure='<img src="banks/earth-3209/assets/u2-211-jun07-52.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Is it the animal itself, or something the animal did?"]);
E("es-u2-211-q04",2,["EA12.2.11"],1,"var",varset([function(){return mcq("Which process produces a fossil in which the pore spaces of an organic material are filled with minerals?","petrification",["carbonization","distillation","freezing"],"Petrification (permineralization) fills the pore spaces of wood or bone with mineral matter, turning the remains to stone while keeping their structure.",{});}]),["The spaces inside the material fill with minerals."]);
E("es-u2-211-q05",2,["EA12.2.11"],2,"var",varset([function(){return mcq("Which fossil is correctly matched with its method of formation? Fossil Method of Formation","foot prints: trace",["bones: mold and cast","coprolites: carbonization","frozen remains: petrification"],"Footprints are the classic trace fossil, the record of an animal's activity. Fossil excrement (coprolites) is also a trace fossil, not carbonization, and frozen remains are preserved whole, not petrified. (House fix: the source printed 'petrifaction'; the standard term is 'petrification'.)",{});}]),["One of these is a record of activity rather than a body part."]);
E("es-u2-211-q06",2,["EA12.2.11"],2,"var",varset([function(){return mcq("Which statement is correct about the fossil of a Miocene worm found in northern Canada?","No part of the worm is preserved.",["It consists of the remains of a hard body part.","The animal burrowed into a tar pit.","The burrow contains insect remains."],"A worm has no hard body parts, so nothing of the worm itself survives; what is preserved is its burrow, a trace fossil. The statement that no part of the worm is preserved is the correct one.",{});}]),["A worm is soft-bodied: what could actually be preserved?"]);

/* ----- EA12.2.12: Geological evidence that life, climate, continental positions and the crust have changed ----- */
E("es-u2-212-q01",2,["EA12.2.12"],2,"var",varset([function(){var q=mcq("Which factor most likely contributed to the position change of fossils in the diagram below?","the environment changed from a forest area to a freshwater lake",["the environment changed from a forest area to a marine environment","the environment changed from an ice-covered area to a marine environment","the environment became drier and more severe over time"],"Reading the column upward, plant fossils (fern, then leaves) give way to freshwater forms (shell, then fish): the area changed from forest to a freshwater lake environment over time.",{});q.figure='<img src="banks/earth-3209/assets/u2-212-jun06-54.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Read the fossils from the bottom (oldest) to the top (youngest)."]);
E("es-u2-212-q02",2,["EA12.2.12"],2,"var",varset([function(){return mcq("What evidence tells geologists that the supercontinent broke apart?","Fossils of Glossopteris are found on many continents.",["Boulders are found at the base of large mountains.","Cephalopods are found on both the Atlantic and Pacific coasts.","Fossil ivy leaves are found in Antarctica."],"Glossopteris was a land plant whose heavy seeds could not cross oceans, yet its fossils occur on South America, Africa, India, Australia and Antarctica. The continents must once have been joined, and have since broken apart and drifted.",{});}]),["The same land plant turns up on continents now separated by oceans."]);
E("es-u2-212-q03",2,["EA12.2.12"],2,"var",varset([function(){return mcq("Coal deposits, formed from lush tropical vegetation, are found in Antarctica. What does this evidence most directly suggest?","Antarctica's climate was once much warmer than it is today.",["Coal can form in any climate, including beneath polar ice caps.","The coal was carried to Antarctica by ocean currents.","Tropical plants are able to grow underneath Antarctic ice."],"Coal forms from dense vegetation in warm, swampy climates. Finding it in Antarctica means that land once supported a tropical climate, direct evidence that climate has changed over geologic time.",{});}]),["What climate does coal formation require?"]);

/* ----- EA12.2.13: The geologic time scale is divided into eons, eras, periods, and epochs ----- */
E("es-u2-213-q01",2,["EA12.2.13"],1,"var",varset([function(){return mcq("Which is the shortest span of geologic time?","epoch",["eon","era","period"],"From longest to shortest, the divisions are eon, era, period, epoch, so the epoch is the shortest span.",{});}]),["Order the four divisions by size."]);
E("es-u2-213-q02",2,["EA12.2.13"],1,"var",varset([function(){return mcq("Which list gives the divisions of the geologic time scale in order from largest to smallest?","eon, era, period, epoch",["epoch, period, era, eon","era, eon, epoch, period","period, epoch, eon, era"],"Eons are divided into eras, eras into periods, and periods into epochs, so the largest-to-smallest order is eon, era, period, epoch.",{});}]),["Each division is split into the next one down."]);

/* ----- EA12.2.14: Precambrian time represents the greatest part of Earth history ----- */
E("es-u2-214-q01",2,["EA12.2.14"],1,"var",varset([function(){return mcq("What is the largest division of time in Earth's history?","Precambrian",["Cenozoic","Mesozoic","Paleozoic"],"Precambrian time runs from Earth's formation to about 541 million years ago, roughly 88 percent of all Earth history, far longer than the three Phanerozoic eras combined.",{});}]),["It covers everything before the Cambrian."]);
E("es-u2-214-q02",2,["EA12.2.14"],2,"var",varset([function(){return mcq("Earth is about 4.6 billion years old, and the Phanerozoic eon began about 541 million years ago. Approximately what percentage of Earth's history does Precambrian time represent?","about 88 percent",["about 12 percent","about 50 percent","about 65 percent"],"Precambrian time spans 4.6 billion minus 0.541 billion, about 4.06 billion years. 4.06 / 4.6 is about 0.88, so Precambrian time is about 88 percent of Earth history. The 12 percent figure is the Phanerozoic share.",{});}]),["Subtract, then divide by Earth's total age."]);

/* ----- EA12.2.15: The Phanerozoic eon represents the emergence of complex life forms ----- */
E("es-u2-215-q01",2,["EA12.2.15"],1,"var",varset([function(){return mcq("The name Phanerozoic means 'visible life'. Why is it an appropriate name for the current eon?","Its rocks preserve abundant fossils of large, complex life forms.",["It is the only eon in which living things existed on Earth.","Life became visible because eyes first evolved during the eon.","The eon's fossils are visible because they are all large dinosaurs."],"Phanerozoic rocks are full of obvious fossils of complex, multicellular organisms with shells, bones and other hard parts. Life existed long before, in the Precambrian, but it was mostly simple and microscopic, so it left a sparse fossil record.",{});}]),["Think about what shows up in the eon's rocks."]);
E("es-u2-215-q02",2,["EA12.2.15"],2,"var",varset([function(){return mcq("Which statement best distinguishes Phanerozoic time from Precambrian time?","Complex multicellular life emerges and diversifies through the Phanerozoic, while Precambrian life was dominated by simple, mostly single-celled organisms.",["Rocks of Phanerozoic age contain no fossils of any kind, because hard body parts had not yet evolved.","Precambrian time lasted only a few million years before complex life appeared at its end.","The Phanerozoic is another name for the Paleozoic era, the first era of complex life."],"The Phanerozoic is the eon of visible, complex life; the Precambrian, which came before it, was dominated by simple organisms. Watch the common mix-up: the Phanerozoic is an eon and contains the Paleozoic, Mesozoic and Cenozoic eras; it is not itself an era.",{});}]),["Eon versus era matters in one of these options."]);

/* ----- EA12.2.16: Distinguish Precambrian time from the Paleozoic, Mesozoic, and Cenozoic eras ----- */
E("es-u2-216-q01",2,["EA12.2.16"],1,"var",varset([function(){return mcq("Which represents the correct chronological order of geologic time?","Precambrian, Paleozoic, Mesozoic, Cenozoic",["Cenozoic, Mesozoic, Paleozoic, Precambrian","Mesozoic, Cenozoic, Paleozoic, Precambrian","Precambrian, Mesozoic, Paleozoic, Cenozoic"],"Precambrian time comes first, followed by the Paleozoic (ancient life), Mesozoic (middle life) and Cenozoic (recent life) eras. (The source prints the sequences with arrows; they are given here as comma lists.)",{});}]),["Ancient, middle, then recent life, after the long Precambrian."]);
E("es-u2-216-q02",2,["EA12.2.16"],1,"var",varset([function(){return mcq("To which geologic era does the Cambrian belong?","Paleozoic",["Cenozoic","Mesozoic","Precambrian"],"The Cambrian is the first period of the Paleozoic era, famous for the rapid diversification of complex life. (The source stem reads 'To which geoloic era'; corrected as a house fix.)",{});}]),["The Cambrian opens the era of ancient life."]);
E("es-u2-216-q03",2,["EA12.2.16"],2,"var",varset([function(){return mcq("The Ediacaran fossils at Mistaken Point in Newfoundland date back 600 million years which places these organisms in which interval of time?","Precambrian",["Cambrian","Mesozoic","Paleozoic"],"600 million years ago is before the Paleozoic era and the Cambrian period begin (about 541 million years ago), so these famous Newfoundland fossils are Precambrian in age.",{});}]),["Compare 600 million years with the start of the Paleozoic."]);

