E("es-u2-217-q02",2,["EA12.2.17"],1,"var",varset([function(){return mcq("During which geologic era did the first land plants appear?","Paleozoic",["Cenozoic","Mesozoic","Precambrian"],"The first land plants appear in the Paleozoic era, and by its later periods great coal forests covered the land.",{});}]),["Land plants predate the dinosaurs by a wide margin."]);
E("es-u2-217-q03",2,["EA12.2.17"],1,"var",varset([function(){return mcq("During which era were dinosaurs the dominant life form on land?","Mesozoic",["Cenozoic","Paleozoic","Precambrian"],"Dinosaurs dominated the land through the Mesozoic era, the age of reptiles, from about 252 to 66 million years ago.",{});}]),["The Mesozoic is the age of reptiles."]);
E("es-u2-217-q04",2,["EA12.2.17"],1,"var",varset([function(){var q=mcq("To which geologic era does the trilobites below belong?","Paleozoic",["Cenozoic","Mesozoic","Precambrian"],"Trilobites are marine arthropods that appear in the Cambrian and thrive through the Paleozoic era, disappearing in the end-Permian extinction.",{});q.figure='<img src="banks/earth-3209/assets/u2-217-aug09-53.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Trilobites are an index fossil group for one whole era."]);
E("es-u2-217-q05",2,["EA12.2.17"],2,"var",varset([function(){return mcq("Which geologic time frame is correctly matched with its dominate life form? Age Dominant Life Form","Paleozoic: amphibians",["Cenozoic: fish","Mesozoic: mammals","Precambrian: reptiles"],"Amphibians were a dominant land group of the later Paleozoic era. Fish arose earlier (Paleozoic) and still thrive; mammals dominate the Cenozoic, not the Mesozoic; reptiles appear in the Paleozoic, long after the Precambrian.",{});}]),["Fish, amphibians, reptiles, mammals: place each group's heyday."]);
E("es-u2-217-q06",2,["EA12.2.17"],2,"var",varset([function(){var q=mcq("Which groups are extinct on the graph below?","trilobites, ammonites, dinosaurs",["ammonites, clams","ammonites, dinosaurs","trilobites, clams"],"On the graph, the range bars for trilobites, ammonites and dinosaurs all end before the present, so all three groups are extinct. Clams range through to the Cenozoic and survive today.",{});q.figure='<img src="banks/earth-3209/assets/u2-217-aug07-58.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["A group is extinct if its bar stops before the present."]);

