E("es-u2-218-q01",2,["EA12.2.18"],1,"var",varset([function(){return mcq("In which time period did trilobites become extinct?","late Paleozoic",["early Cenozoic","late Mesozoic","late Precambrian"],"Trilobites survived the whole Paleozoic era but disappeared in the end-Permian mass extinction, at the end of the late Paleozoic.",{});}]),["Trilobites vanish in the greatest mass extinction, ending their era."]);
E("es-u2-218-q02",2,["EA12.2.18"],1,"var",varset([function(){return mcq("When did dinosaurs become extinct?","end of Mesozoic",["beginning of Paleozoic","end of Paleozoic","middle of Cenozoic"],"Dinosaurs (other than birds) became extinct 66 million years ago, at the end of the Mesozoic era, the boundary with the Cenozoic.",{});}]),["Their extinction closes the era they dominated."]);
E("es-u2-218-q03",2,["EA12.2.18"],2,"var",varset([function(){return mcq("Which correctly shows the evolution of life on Earth?","fish, amphibian, reptiles, mammals",["amphibian, reptiles, mammals, fish","mammals, reptiles, amphibian, fish","reptiles, mammals, fish, amphibian"],"Life moved from water to land in this order: fish first, then amphibians, then reptiles, then mammals. (The source prints the sequences with arrows; they are given here as comma lists.)",{});}]),["The sequence follows the move from water to land."]);
E("es-u2-218-q04",2,["EA12.2.18"],2,"var",varset([function(){return mcq("Which represents the correct order in which organisms appeared on Earth?","trilobites, amphibians, reptiles, mammals",["amphibians, trilobites, mammals, reptiles","mammals, reptiles, amphibians, trilobites","trilobites, reptiles, amphibians, mammals"],"Trilobites appear in the Cambrian seas, amphibians in the later Paleozoic, reptiles after them, and mammals last. (The source prints the sequences with arrows; they are given here as comma lists.)",{});}]),["Trilobites are Cambrian; mammals come last."]);
E("es-u2-218-q05",2,["EA12.2.18"],2,"var",varset([function(){return mcq("Which is the correct pairing of the geological boundary and the extinction of major life forms? Geological Boundary Extinction of Life Forms","Paleozoic/Mesozoic: Marine Invertebrates",["Mesozoic/Cenozoic: Mammals","Precambrian/Paleozoic: Land Plants","Precambrian/Paleozoic: Reptiles"],"The end-Permian extinction at the Paleozoic/Mesozoic boundary wiped out the great majority of marine invertebrate species. Mammals were not extinguished at the Mesozoic/Cenozoic boundary (they rose after it), and neither land plants nor reptiles existed at the Precambrian/Paleozoic boundary to become extinct.",{});}]),["One boundary hosts the largest extinction of all."]);
E("es-u2-218-q06",2,["EA12.2.18"],3,"var",varset([function(){return mcq("If fossils of animals with shells were found in rock that existed 800 million years ago, how would this change the geologic time scale?","Paleozoic boundary would begin at 800 million years.",["Dinosaurs would appear in the early Paleozoic","Mesozoic would include the last 800 million years","Trilobites would move to the Cretaceous"],"The Paleozoic is defined by the appearance of abundant shelled, complex life. Finding shelled animals at 800 million years would push the base of the Paleozoic (and the Phanerozoic) back to that age.",{});}]),["What event currently defines the base of the Paleozoic?"]);

/* ----- EA12.2.19: Recognize that life forms, climate, continental positions, and Earth's crust have changed over time ----- */
E("es-u2-219-q01",2,["EA12.2.19"],2,"var",varset([function(){return mcq("Which environment did the trilobite live in?","shallow marine and low energy",["deep ocean marine and high energy","freshwater and high energy","freshwater and low energy"],"Trilobites were bottom-dwelling marine animals. Their flat, segmented bodies and delicate appendages suit quiet, shallow marine water, and their fossils occur in shallow-marine rocks.",{});}]),["Trilobites are marine, and their build suits calm water."]);
E("es-u2-219-q02",2,["EA12.2.19"],2,"var",varset([function(){return mcq("Which best compares oxygen concentration in Earth's atmosphere over time? Precambrian Cenozoic","Precambrian: low; Cenozoic: high",["Precambrian: high; Cenozoic: high","Precambrian: high; Cenozoic: low","Precambrian: low; Cenozoic: low"],"Early Earth had almost no free oxygen; oxygen built up through the Precambrian as photosynthetic organisms released it, reaching high levels by the Cenozoic.",{});}]),["Free oxygen is a product of early life."]);
E("es-u2-219-q03",2,["EA12.2.19"],1,"var",varset([function(){return mcq("Which observation is evidence that life on Earth has changed over time?","Fossil species common in older rock layers are absent from younger layers and from the living world.",["Rivers carry sediment from the land and deposit it in the sea.","Rock layers in a cliff face are stacked one on top of another.","The same species of fish is found in oceans around the world today."],"Species that vanish from the fossil record and are not alive today show that the set of living things has changed over geologic time. The other observations describe present-day processes or rock order, not change in life.",{});}]),["Look for something that used to live but no longer does."]);

