/* ----- EA12.3.1: Define mineral chemistry terms ----- */
E("es-u3-31-q01",3,["EA12.3.1"],1,"var",varset([function(){return mcq("Which is negatively charged?","electron",["isotope","neutron","proton"],"Electrons carry a negative charge. Protons are positive and neutrons have no charge; an isotope is a form of an element, not a particle charge.",{});}]),["Recall the charges on the three subatomic particles."]);
E("es-u3-31-q02",3,["EA12.3.1"],1,"var",varset([function(){return mcq("Which always consists of only one type of atom?","element",["compound","molecule","hydrate"],"An element consists of only one type of atom. Compounds and molecules combine two or more elements, and a hydrate also contains water.",{});}]),["Think of the simplest possible pure substance."]);
E("es-u3-31-q03",3,["EA12.3.1"],1,"var",varset([function(){return mcq("What are atoms of the same element that contain different numbers of neutrons called?","Isotopes",["Compounds","Ions","Protons"],"Atoms of the same element with different neutron counts, and therefore different masses, are isotopes. The proton count, which defines the element, stays the same.",{});}]),["Same protons, different neutrons."]);

/* ----- EA12.3.2: Describe how atoms combine to form compounds ----- */
E("es-u3-32-q01",3,["EA12.3.2"],1,"var",varset([function(){return mcq("What is formed when chemical bonding joins two or more elements together in definite proportions?","compound",["atom","isotope","molecule"],"When bonding joins two or more elements in definite proportions, the result is a compound.",{});}]),["The key phrase is definite proportions."]);
E("es-u3-32-q02",3,["EA12.3.2"],1,"var",varset([function(){return mcq("Which describes the covalent bonding that occurs between atoms in a water molecule ?","sharing of electrons",["sharing of protons","transfer of electrons","transfer of protons"],"In covalent bonding, atoms share electrons. Water forms when hydrogen and oxygen share electrons in this way.",{});}]),["Covalent and ionic bonding differ in what happens to the electrons."]);
E("es-u3-32-q03",3,["EA12.3.2"],1,"var",varset([function(){return mcq("Which consists of at least two elements?","compounds",["atoms","electrons","protons"],"A compound consists of at least two elements chemically combined. Atoms, electrons and protons are single particles or single elements.",{});}]),["Only one of the choices names something made of more than one element."]);

/* ----- EA12.3.3: Outline the abundance of the elements that comprise Earth’s crust ----- */
E("es-u3-33-q01",3,["EA12.3.3"],1,"var",varset([function(){return mcq("What is the most abundant element in Earth’s crust?","oxygen",["iron","nickel","silicon"],"Oxygen is the single most abundant element in Earth's crust, at roughly 47 percent by weight.",{});}]),["It is not a metal, and it is not silicon."]);
E("es-u3-33-q02",3,["EA12.3.3"],1,"var",varset([function(){return mcq("Which elements are most abundant in Earth’s crust?","silicon and oxygen",["aluminum and carbon","aluminum and oxygen","silicon and carbon"],"Oxygen and silicon together make up about three quarters of the crust by weight, so silicon and oxygen are the most abundant pair.",{});}]),["Two elements dominate the crust, and both are in the key."]);
E("es-u3-33-q03",3,["EA12.3.3"],1,"var",varset([function(){return mcq("What are the two most common elements in Earth’s crust?","oxygen and silicon",["iron and aluminum","iron and silicon","oxygen and aluminum"],"Oxygen (about 47 percent) and silicon (about 28 percent) are the two most common elements in Earth's crust.",{});}]),["Together they account for about three quarters of the crust."]);
E("es-u3-33-q04",3,["EA12.3.3"],2,"var",varset([function(){return mcq("Which element is NOT one of the eight most abundant elements in Earth's continental crust?","Hydrogen",["Aluminum","Calcium","Iron"],"The eight most abundant elements in the continental crust are oxygen, silicon, aluminum, iron, calcium, sodium, potassium and magnesium. Hydrogen is not among them.",{});}]),["The crust's top eight are mostly rock-forming metals plus oxygen and silicon."]);

/* ----- EA12.3.4: Define a mineral ----- */
E("es-u3-34-q01",3,["EA12.3.4"],1,"var",varset([function(){return mcq("Which is a mineral?","gypsum",["coal","oil","sandstone"],"Gypsum is a naturally occurring, inorganic, solid substance with a definite composition, so it is a mineral. Coal and oil are organic, and sandstone is a rock.",{});}]),["Apply all five parts of the mineral definition."]);
E("es-u3-34-q02",3,["EA12.3.4"],1,"var",varset([function(){return mcq("Which is a substance that is solid, inorganic, occurs naturally, and exhibits a definite chemical composition and molecular structure?","mineral",["electron","isotope","rock"],"The description lists the defining traits of a mineral: solid, inorganic, naturally occurring, with definite chemical composition and molecular structure.",{});}]),["Match the description to the term it defines."]);
E("es-u3-34-q03",3,["EA12.3.4"],1,"var",varset([function(){return mcq("Which is true regarding a mineral?","It is naturally occurring.",["It is a gas.","It is an organic compound.","It is impure."],"A mineral must be naturally occurring. It is a solid, not a gas, and it is inorganic rather than an organic compound.",{});}]),["Check each statement against the mineral definition."]);
E("es-u3-34-q04",3,["EA12.3.4"],2,"var",varset([function(){return mcq("Which statement about minerals is NOT true?","Minerals are organic.",["Minerals are formed of atoms.","Minerals are naturally occurring.","Minerals have a definite chemical structure.","Minerals are solid."],"Minerals are inorganic by definition, so the organic statement is the false one. The rest are all part of the definition of a mineral.",{});}]),["One statement contradicts the mineral definition directly."]);

/* ----- EA12.3.5: Recognize the relationship between the abundance of the elements that comprise Earth’s crust and the mineral groups ----- */
E("es-u3-35-q01",3,["EA12.3.5"],2,"var",varset([function(){return mcq("Oxygen and silicon together make up about 75 percent of Earth's crust. What does this explain about the minerals of the crust?","Silicate minerals, built from oxygen and silicon, are the most common minerals in the crust.",["Carbonate minerals dominate the crust because carbon dioxide is in the air.","Most crustal minerals are native elements found in their pure form.","Sulfide minerals are the most common minerals in the crust."],"Mineral abundance follows element abundance: because the crust is mostly oxygen and silicon, the minerals built from those two elements, the silicates, dominate the crust.",{});}]),["Match the most abundant elements to the mineral group built from them."]);
E("es-u3-35-q02",3,["EA12.3.5"],1,"var",varset([function(){return mcq("Which mineral group is the most abundant in Earth's crust, matching the crust's most abundant elements?","The silicates",["The carbonates","The oxides","The sulfates"],"Silicates are the most abundant mineral group because the crust itself is mostly oxygen and silicon, the two elements every silicate contains.",{});}]),["The group's name contains the crust's second most abundant element."]);

/* ----- EA12.3.6: Name and differentiate between the major mineral groups ----- */
E("es-u3-36-q01",3,["EA12.3.6"],1,"var",varset([function(){return mcq("Which is a native element in Earth’s crust?","gold",["aluminum","magnesium","sodium"],"Gold occurs in its pure form in nature, so it is a native element. Aluminum, magnesium and sodium occur combined in compounds.",{});}]),["A native element is found uncombined in nature."]);
E("es-u3-36-q02",3,["EA12.3.6"],1,"var",varset([function(){return mcq("In which mineral group does olivine (Mg2SiO4) belong?","silicate",["carbonate","halide","sulfate"],"Olivine's formula contains silicon and oxygen (SiO4), which makes it a silicate, the largest mineral group.",{});}]),["Look for silicon and oxygen in the formula."]);
E("es-u3-36-q03",3,["EA12.3.6"],1,"var",varset([function(){return mcq("In which mineral group does pyrite (FeS2) belong?","sulfides",["halides","oxides","sulfates"],"Pyrite contains sulfur combined with a metal and no oxygen, which places it in the sulfide group. (House fix: the sample final printed pyrite's formula as FeS; pyrite is FeS2.)",{});}]),["The sulfur in the formula is the clue."]);
E("es-u3-36-q04",3,["EA12.3.6"],1,"var",varset([function(){return mcq("Which mineral group is a nonsilicate group?","Carbonates",["Feldspars","Micas","Quartz"],"Carbonates, built on the carbonate ion (CO3), are a nonsilicate group. Feldspars, micas and quartz are all silicates, built on silicon and oxygen.",{});}]),["Three of the groups are built on the silicon-oxygen tetrahedron."]);

/* ----- EA12.3.7: Identify mineral groups based on mineral formulas ----- */
E("es-u3-37-q01",3,["EA12.3.7"],2,"var",varset([function(){return mcq("Which chemical formula is matched with its mineral group? Chemical Formula Mineral Group","Fe2O3: oxides",["Al2O3: halides","CaSO4: sulfides","ZnS: sulfates"],"Fe2O3 contains a metal combined with oxygen only, so it is an oxide. The other pairings mismatch the anion in each formula.",{});}]),["Identify the anion in each formula first."]);
E("es-u3-37-q02",3,["EA12.3.7"],1,"var",varset([function(){return mcq("Which formula is matched to the correct mineral group?","BaSO4: sulfate",["CaCO3: oxide","Fe3O4: carbonate","ZnS: halide"],"BaSO4 contains the sulfate ion (SO4), so it is a sulfate. CaCO3 is a carbonate, Fe3O4 is an oxide, and ZnS is a sulfide.",{});}]),["Match each formula to its anion group."]);
E("es-u3-37-q03",3,["EA12.3.7"],1,"var",varset([function(){return mcq("Which is a sulfate mineral?","CaSO4·2H2O",["CaMg(CO3)2","KCl","ZnS"],"Gypsum, CaSO4·2H2O, contains the sulfate ion, so it is a sulfate mineral.",{});}]),["One formula contains SO4."]);

/* ----- EA12.3.8: Describe the arrangement of silicon and oxygen within a tetrahedron ----- */
E("es-u3-38-q01",3,["EA12.3.8"],1,"var",varset([function(){return mcq("What does the basic building block of the silicate minerals contain?","1 silicon atom and 4 oxygen atoms",["1 oxygen atom and 4 silicon atoms","2 iron atoms for each silicon atom","4 silicon atoms and 4 oxygen atoms"],"The silicon-oxygen tetrahedron, the building block of every silicate mineral, holds one silicon atom bonded to four oxygen atoms.",{});}]),["The block is named for silicon and oxygen, in that order."]);
E("es-u3-38-q02",3,["EA12.3.8"],1,"var",varset([function(){return mcq("How are the atoms arranged in a silicon-oxygen tetrahedron?","One silicon atom sits at the centre, bonded to four oxygen atoms at the corners.",["Four silicon atoms surround one oxygen atom at the centre.","Silicon and oxygen atoms alternate in a flat square.","The atoms form a cube with silicon at every corner."],"A tetrahedron is a four-sided pyramid: the small silicon atom sits in the middle and an oxygen atom occupies each of the four corners.",{});}]),["Tetra means four: count the oxygen atoms at the corners."]);
E("es-u3-38-q03",3,["EA12.3.8"],2,"var",varset([function(){return mcq("In quartz, every oxygen atom in the tetrahedra is shared between two tetrahedra, locking them into a continuous three-dimensional framework. What property of quartz does this explain?","Quartz is hard and has no cleavage, breaking with conchoidal fracture instead.",["Quartz is soft and splits easily into flat sheets along one perfect cleavage.","Quartz dissolves readily in weak acids and fizzes when acid is dropped on it.","Quartz has a low specific gravity and breaks into blocky fragments with ease."],"Because the bonding is equally strong in every direction, quartz has no weak planes to split along. It is hard (7 on Moh's scale) and breaks with conchoidal fracture rather than cleaving.",{});}]),["Cleavage needs planes of weak bonding; a full framework has none."]);

/* ----- EA12.3.9: Describe the mineral properties that are used for identifying minerals ----- */
E("es-u3-39-q01",3,["EA12.3.9"],2,"var",varset([function(){return mcq("A sample of galena has a mass of 160 g and displaces 20 mL of water. What is its specific gravity?","8",["4","16","160"],"Specific gravity equals density here: 160 g / 20 mL = 8 g/mL, so the specific gravity is 8.",{});}]),["Divide the mass by the volume of water displaced."]);
E("es-u3-39-q02",3,["EA12.3.9"],2,"var",varset([function(){return mcq("Given the information below, what is the order of minerals from softest to hardest? • Corundum scratches quartz. • Quartz scratches calcite. • Calcite scratches talc. softest hardest","talc → calcite → quartz → corundum",["corundum → quartz → calcite → talc","corundum → quartz → talc → calcite","talc → calcite → corundum → quartz"],"Reverse the scratch results: corundum scratches quartz, quartz scratches calcite, and calcite scratches talc, so from softest to hardest the order is talc, calcite, quartz, corundum.",{});}]),["Whatever is scratched is the softer mineral."]);
E("es-u3-39-q03",3,["EA12.3.9"],2,"var",varset([function(){return mcq("A prospector is trying to determine the name of a mineral by measuring hardness. The mineral can be scratched by an iron nail and glass but cannot be scratched by a copper penny or fingernail. What is the mineral? (Moh's scale: talc 1, gypsum 2, calcite 3, fluorite 4, apatite 5, feldspar 6, quartz 7, topaz 8, corundum 9, diamond 10. Common objects: fingernail 2.5, copper penny 3.5, iron nail 4.5, glass 5.5, steel file 6.5.)","Fluorite",["Apatite","Calcite","Quartz"],"The mineral's hardness lies between the copper penny (3.5) and the iron nail (4.5): it is scratched by the nail but not by the penny. Fluorite, at hardness 4, is the only listed mineral in that range.",{});}]),["Bracket the hardness between the softest object that scratches it and the hardest that cannot."]);
E("es-u3-39-q04",3,["EA12.3.9"],2,"var",varset([function(){var q=mcq("Which mineral exhibits the cleavage pattern shown below?","mica",["calcite","feldspar","halite"],"The diagram shows thin, flexible sheets peeling apart, the one-directional cleavage of mica.",{});q.figure='<img src="banks/earth-3209/assets/u3-39-jun08-17.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Which mineral splits into thin sheets?"]);
E("es-u3-39-q05",3,["EA12.3.9"],1,"var",varset([function(){return mcq("What is the fracture shown by minerals, such as quartz, that break into smooth, curved surfaces like broken glass?","Conchoidal fracture",["Earthy fracture","Fibrous fracture","Uneven fracture"],"Smooth, curved breakage surfaces like those in broken glass are conchoidal fracture, typical of quartz and glass, which have no cleavage planes.",{});}]),["The name comes from the shell-like curve of the surface."]);
E("es-u3-39-q06",3,["EA12.3.9","EA12.3.10"],3,"var",varset([function(){return mcq("A mineral sample is glassy, has a hardness of about 6, shows no cleavage, and has a specific gravity of 2.65. Which mineral is it?","Quartz",["Calcite","Fluorite","Orthoclase feldspar"],"The data set fits quartz: hardness 6 to 7, specific gravity 2.65, glassy lustre and no cleavage. Calcite is softer (3) and reacts with acid, fluorite is softer (4) with perfect cleavage, and orthoclase shows two cleavage directions.",{});}]),["Test each candidate against all four measurements, not just one."]);

/* ----- EA12.3.10: Identify minerals based on their mineral properties and explain why minerals exhibit different mineral properties ----- */
E("es-u3-310-q01",3,["EA12.3.10"],2,"var",varset([function(){return mcq("Which best explains why diamond is much harder than graphite?","atomic arrangement",["cleavage","impurities","specific gravity"],"Diamond and graphite have the same composition (carbon) but different atomic arrangements. Diamond's tightly bonded three-dimensional network makes it much harder than graphite's loosely bonded sheets.",{});}]),["Same atoms, different structure."]);
E("es-u3-310-q02",3,["EA12.3.10"],2,"var",varset([function(){return mcq("Which is the least reliable indicator of a mineral’s identity?","colour",["cleavage","hardness","streak"],"Colour is the least reliable indicator because a single mineral can occur in many colours and many minerals share the same colour. Cleavage, hardness and streak are far more consistent.",{});}]),["Think of quartz, which occurs in many colours."]);
E("es-u3-310-q03",3,["EA12.3.10"],3,"var",varset([function(){return mcq("The specific gravity of four white-coloured minerals is listed in the chart below. A geologist has discovered a mineral sample that has a mass of 85 grams and a volume of 19.1 milliliters. What is the name of the sample? Mineral Specific Gravity","barite (specific gravity 4.45)",["calcite (specific gravity 2.71)","fluorite (specific gravity 3.18)","quartz (specific gravity 2.65)"],"Specific gravity = 85 g / 19.1 mL = 4.45, which matches barite in the chart.",{});}]),["Compute the specific gravity, then match it to the chart."]);
E("es-u3-310-q04",3,["EA12.3.10"],3,"var",varset([function(){return mcq("Based on the description below, which type of mineral does the geologist have? A geologist has a sample that looks like quartz. It has a rhombohedral shape and demonstrates double refraction. She places a drop of acid on it and notices bubbles forming.","calcite",["chalcopyrite","diamond","fluorite"],"Rhombohedral shape, double refraction and fizzing in acid are diagnostic of calcite, even though the sample resembles quartz. Quartz does not react with acid and has no cleavage.",{});}]),["The acid test result decides this one."]);

/* ----- EA12.8.1: Identify careers that relate to mineral chemistry ----- */
E("es-u3-81-q01",3,["EA12.8.1"],1,"var",varset([function(){return mcq("Which career works most directly with mineral chemistry, testing ore samples to determine their metal content before a mine makes production decisions?","An assayer in a geochemistry laboratory",["A cartographer drawing topographic maps","A meteorologist forecasting weather","A seismologist monitoring earthquakes"],"Assayers and geochemists analyse the chemical composition of mineral and ore samples, the direct workplace use of mineral chemistry.",{});}]),["The job is analysing what minerals are made of."]);
E("es-u3-81-q02",3,["EA12.8.1"],2,"var",varset([function(){return mcq("A mining company must decide whether a drill core contains enough copper minerals to be worth processing. Which specialist's knowledge of mineral chemistry is most directly needed?","A mineralogist, who identifies the copper minerals and grades their composition",["A gemologist, who grades the colour and cut of finished gemstones","A paleontologist, who identifies fossils in the core samples","A volcanologist, who monitors gases at active volcanoes"],"Identifying which copper minerals are present, and in what proportions, is mineralogy applied to an economic decision, the core of mineral chemistry in the mining industry.",{});}]),["The decision turns on which minerals are in the rock and how much metal they hold."]);

