E("es-u3-311-q02",3,["EA12.3.11"],2,"var",varset([function(){return mcq("A rock sample is made almost entirely of the single mineral calcite. Which rock is it most likely to be?","Limestone",["Granite","Sandstone","Shale"],"Limestone is a monomineralic rock, made almost entirely of calcite. Granite, sandstone and shale each contain several minerals or mineral fragments.",{});}]),["One of these rocks is named for a single mineral's chemistry."]);

/* ----- EA12.8.2: Analyse the rock cycle as a natural system and explain its structure and dynamics ----- */
E("es-u3-82-q01",3,["EA12.8.2"],2,"var",varset([function(){var q=mcq("Which rock type will form at location Z in the diagram below?","intrusive igneous",["chemical sedimentary","clastic sedimentary","extrusive igneous"],"Location Z marks magma bodies cooling inside the continental crust. Rock that crystallizes from magma below the surface is intrusive igneous rock.",{});q.figure='<img src="banks/earth-3209/assets/u3-82-jun08-39.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Find what is happening at Z: magma cooling underground."]);
E("es-u3-82-q02",3,["EA12.8.2"],2,"var",varset([function(){return mcq("Which statement is true about the rock cycle?","sedimentary rocks may contain igneous and metamorphic rocks",["magma cools and crystallizes to form metamorphic rocks","metamorphic rocks lithify to form sediments","weathering affects only igneous rocks"],"Sedimentary rocks form from fragments of any older rock, so they may contain pieces of igneous and metamorphic rocks. Magma crystallizes into igneous rock, metamorphic rocks weather into sediments rather than lithifying into them, and weathering affects all rock types.",{});}]),["Test each statement against the rock cycle diagram."]);
E("es-u3-82-q03",3,["EA12.8.2"],3,"var",varset([function(){return mcq("Based on the information below, which rock type(s) would a geologist expect to find? The discovery of a planet reveals no atmosphere or liquid water and plate tectonic activity has been occurring.","igneous only",["igneous and metamorphic","metamorphic only","sedimentary and metamorphic"],"With no atmosphere or liquid water there is no weathering, erosion or deposition, so sedimentary rock cannot form. Plate tectonics still melts and deforms rock, so igneous rock forms and can be changed into metamorphic rock.",{});}]),["Work through which rock types need surface water and air."]);
E("es-u3-82-q04",3,["EA12.8.2"],1,"var",varset([function(){return mcq("Which rock type makes up the great majority of the rocks exposed at Earth's surface?","Sedimentary rocks",["Igneous rocks","Metamorphic rocks","Volcanic rocks"],"Sedimentary rocks cover most of the surface as a thin veneer, even though igneous and metamorphic rocks make up most of the crust's volume below.",{});}]),["Surface exposure and total volume give different answers; this asks about exposure."]);

/* ----- EA12.3.12: Recognize that igneous rocks are classified according to their mineral composition and texture ----- */
E("es-u3-312-q01",3,["EA12.3.12"],1,"var",varset([function(){return mcq("Which forms from the crystallization of magma?","igneous",["clastic","evaporite","metamorphic"],"Igneous rock forms from the crystallization of magma (or lava). Clastic and evaporite are sedimentary classes, and metamorphic rock forms from altered pre-existing rock.",{});}]),["Crystallization of molten rock defines one rock family."]);
E("es-u3-312-q02",3,["EA12.3.12"],1,"var",varset([function(){return mcq("What is molten rock material found beneath Earth's surface called?","Magma",["Lava","Mineraloid","Plasma"],"Molten rock below the surface is magma. It is called lava only once it reaches the surface.",{});}]),["The name changes when it erupts."]);
E("es-u3-312-q03",3,["EA12.3.12"],2,"var",varset([function(){return mcq("Why can two igneous rocks contain the same minerals yet have different names?","They have different textures.",["Igneous rock names are arbitrary.","They were found in different places.","They have different colours."],"Igneous rocks are named by texture as well as composition: granite and rhyolite hold the same minerals, but granite's coarse texture records slow cooling underground and rhyolite's fine texture records rapid cooling at the surface.",{});}]),["Composition is only half of igneous classification."]);

/* ----- EA12.3.13: Describe how mafic igneous rocks differ from felsic igneous rocks based on chemical composition. ----- */
E("es-u3-313-q01",3,["EA12.3.13"],3,"var",varset([function(){var q=mcq("From the graph below, which best describes the concentration of pyroxene in felsic and mafic rocks? Felsic Mafic","Felsic: low; Mafic: high",["Felsic: high; Mafic: high","Felsic: high; Mafic: low","Felsic: low; Mafic: low"],"On the chart, pyroxene makes up almost none of the felsic (granite) band but a large share of mafic rocks such as gabbro, so its concentration is low in felsic rocks and high in mafic rocks.",{});q.figure='<img src="banks/earth-3209/assets/u3-313-aug06-24.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Read the pyroxene band at the granite end and at the gabbro end."]);
E("es-u3-313-q02",3,["EA12.3.13"],2,"var",varset([function(){return mcq("Which best explains the difference in density between continental and oceanic crust?","composition",["crystallization","porosity","state"],"Oceanic crust is denser because of its mafic composition, rich in iron and magnesium, while continental crust is less dense felsic material. The difference is composition, not porosity or state.",{});}]),["Density differences between the two crusts come from what they are made of."]);
E("es-u3-313-q03",3,["EA12.3.13"],2,"var",varset([function(){return mcq("What is the correct match for magma composition and environment? Magma Composition Environment","Mafic magma: ridge",["Felsic magma: divergent boundary","Felsic magma: hot spots","Mafic magma: transform boundary"],"Mafic magma is the basaltic magma erupted at ocean ridges, where plates diverge and new oceanic crust forms.",{});}]),["Ocean ridges are built from one magma type."]);
E("es-u3-313-q04",3,["EA12.3.13"],2,"var",varset([function(){return mcq("To what is a magma's viscosity most directly related?","Its silica content",["Its age","Its colour","Its depth"],"Silica content controls viscosity: silica-rich felsic magma is thick and resistant to flow, while silica-poor mafic magma is runny.",{});}]),["It is a property of the magma's chemistry."]);

