E("es-u3-314-q01",3,["EA12.3.14"],1,"var",varset([function(){return mcq("Which pair of rocks have the same mineral composition?","gabbro and basalt",["andesite and basalt","andesite and rhyolite","gabbro and rhyolite"],"Gabbro and basalt share the same mafic mineral composition; gabbro is the coarse-grained intrusive form and basalt its fine-grained extrusive equivalent.",{});}]),["Look for an intrusive and extrusive pair with the same composition."]);
E("es-u3-314-q02",3,["EA12.3.14"],3,"var",varset([function(){return mcq("Using the diagram below, what is the volcanic equivalent of a rock that has 55% plagioclase feldspar, 25% hornblende and 20% pyroxene?","andesite",["basalt","komatiite","rhyolite"],"The percentages plot in the Diorite/Andesite column of the chart: plagioclase is dominant with hornblende and pyroxene. The volcanic (extrusive) equivalent of diorite is andesite.",{});}]),["Find which column the three percentages fit, then take its volcanic rock name."]);

