E("es-u3-322-q02",3,["EA12.3.22"],2,"var",varset([function(){return mcq("Which rock type consists of angular particles formed from gravel deposited close to the source of weathering?","breccia",["conglomerate","sandstone","shale"],"Angular particles of gravel size, deposited close to their source, form breccia. Conglomerate's particles are rounded by longer transport.",{});}]),["Angular versus rounded is the deciding detail."]);

