E("es-u3-323-q01",3,["EA12.3.23"],2,"var",varset([function(){var q=mcq("What would a geologist determine from the section of sedimentary rock below?","Feldspar grains have traveled a shorter distance than other types of grains.",["Feldspar grains are harder than other types of grains.","Quartz grains are softer than other types of grains.","Quartz grains have traveled a shorter distance than other types of grains."],"In the section, the feldspar grains are still angular while the quartz grains are rounded. Feldspar is softer and weathers quickly, so angular feldspar grains cannot have travelled far; they were deposited a shorter distance from their source.",{});q.figure='<img src="banks/earth-3209/assets/u3-323-jun08-24.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Angular grains have not been transported far, and feldspar does not survive long trips."]);
E("es-u3-323-q02",3,["EA12.3.23"],1,"var",varset([function(){var q=mcq("Which diagram shows a well-sorted sediment?","",["","",""],"Diagram A shows grains that are all about the same size, which is what well sorted means. The other diagrams mix large and small grains.",{});q.figure='<img src="banks/earth-3209/assets/u3-323-jun08-26.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Well sorted means a narrow size range."]);
E("es-u3-323-q03",3,["EA12.3.23"],2,"var",varset([function(){return mcq("Which property best distinguishes sediment deposited by a river from sediment deposited by a glacier?","amount of sediment sorting",["age of fossils found in the sediment","mineral composition of the sediment","thickness of sediment layers"],"River sediment is sorted by flowing water, while a glacier deposits its load unsorted, so the amount of sorting best distinguishes the two.",{});}]),["Think about what moving water does that ice does not."]);
E("es-u3-323-q04",3,["EA12.3.23"],3,"var",varset([function(){return mcq("A sandstone contains grains that are well rounded but range widely in size from fine sand to pebbles. What does this combination indicate about the sediment's history?","The grains were transported far enough to be rounded, but were deposited by an agent, such as a glacier or debris flow, that did not sort them by size.",["The grains were deposited close to their source, where a fast, turbulent river rounded them quickly but had no time to sort them by size.","The grains were transported a long distance by a steady river that rounded them by abrasion and sorted them thoroughly on the way.","The grains formed in place where the bedrock weathered, so no transporting agent ever moved, rounded or arranged them."],"Rounding records a long transport history, but the wide size range shows poor sorting. Running water rounds and sorts together, so the mismatch points to an agent like ice or a debris flow, which carries all sizes and drops them together.",{});}]),["Treat rounding and sorting as two separate pieces of evidence."]);

