E("es-u3-324-q02",3,["EA12.3.24"],1,"var",varset([function(){return mcq("Which sediment type is found in a very low velocity environment?","mud",["gravel with angular fragments","gravel with rounded fragments","sand"],"Only mud-sized particles settle out in a very low velocity environment; gravel and sand need faster water to move and drop out sooner as water slows.",{});}]),["The slowest water can carry only the finest material."]);

