E("es-u3-325-q02",3,["EA12.3.25"],2,"var",varset([function(){var q=mcq("Which type of depositional environment is illustrated in the diagram below?","desert",["river","marine","shoreline"],"The crescent-shaped barchan dunes in the diagram are built by wind in a desert environment.",{});q.figure='<img src="banks/earth-3209/assets/u3-325-aug07-29.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Crescent dunes form where sand is moved by wind."]);
