E("es-u3-327-q01",3,["EA12.3.27"],2,"var",varset([function(){return mcq("Which mineral forms in a hot, shallow marine environment?","gypsum",["feldspar","olivine","quartz"],"Gypsum precipitates in hot, shallow marine water as evaporation concentrates the dissolved minerals past saturation.",{});}]),["Evaporite minerals form where seawater evaporates."]);
E("es-u3-327-q02",3,["EA12.3.27"],2,"var",varset([function(){return mcq("Thick beds of rock salt and gypsum are found in a region that is now dry land. What environment do these chemical sedimentary rocks record?","A restricted sea or salt lake in an arid climate, where evaporation exceeded inflow",["A deep ocean basin far from land, where fine mud settles slowly out of the water","A glacial valley filled with meltwater from a melting ice sheet each spring","A river delta in a wet tropical climate, where heavy rain flushes sediment to the sea"],"Rock salt and gypsum are evaporites: they precipitate only where evaporation concentrates brine faster than fresh water can dilute it, as in restricted seas and salt lakes under arid skies.",{});}]),["These minerals need water to disappear, not to flow."]);

