E("es-u3-329-q02",3,["EA12.3.29"],1,"var",varset([function(){return mcq("Which is the correct sequence for the formation of coal?","peat → lignite → bituminous → anthracite",["anthracite → peat → bituminous → lignite","anthracite → bituminous → lignite → peat","peat → anthracite → lignite → bituminous"],"Coal forms in the sequence peat, lignite, bituminous coal, anthracite, as burial adds heat and pressure and drives off water and gases.",{});}]),["Start with the spongy plant material in the swamp."]);
