E("es-u3-331-q02",3,["EA12.3.31"],1,"var",varset([function(){return mcq("What is the single most characteristic feature of sedimentary rocks?","Strata (layering)",["Crystals","Mud cracks","Ripple marks"],"Strata, the layered beds laid down one on another, are the most characteristic feature of sedimentary rocks. Mud cracks and ripple marks occur only in some beds.",{});}]),["It is the feature that comes from deposition itself."]);

