E("es-u3-332-q03",3,["EA12.3.32"],1,"var",varset([function(){return mcq("Which is NOT an agent of metamorphism?","Lithification",["Chemically active fluids","Heat","Pressure"],"Metamorphism is driven by heat, pressure and chemically active fluids. Lithification, the compaction and cementing of sediment, makes sedimentary rock instead.",{});}]),["One choice belongs to sedimentary rock formation."]);

