E("es-u3-334-q02",3,["EA12.3.34"],3,"var",varset([function(){var q=mcq("If the magma chamber in the diagram below is granitic and the continental crust at “X” is granite, which type of metamorphic rock would be found at “Y” and which extrusive igneous rock would form during an eruption occurring at “Z”? Metamorphic Rock at Extrusive Igneous Rock “Y” at “Z”","Metamorphic rock at Y: gneiss; Extrusive igneous rock at Z: rhyolite",["Metamorphic rock at Y: gneiss; Extrusive igneous rock at Z: basalt","Metamorphic rock at Y: marble; Extrusive igneous rock at Z: basalt","Metamorphic rock at Y: marble; Extrusive igneous rock at Z: rhyolite"],"Granite metamorphosed by the heat of the magma chamber becomes gneiss at Y, and the granitic (felsic) magma erupting at Z cools as rhyolite, its extrusive equivalent.",{});q.figure='<img src="banks/earth-3209/assets/u3-334-final-27.png" alt="Diagram for this question" style="max-width:100%;height:auto">';return q;}]),["Y takes the parent rock (granite) plus heat; Z takes the magma type (granitic) to the surface."]);
E("es-u3-334-q03",3,["EA12.3.34"],2,"var",varset([function(){return mcq("Which is the correct match between parent rock and metamorphic rock? Parent Rock Metamorphic Rock","Black shale: schist",["Granite: marble","Limestone: quartzite","Quartz sandstone: gneiss"],"Black shale metamorphoses into schist at higher grades. Granite forms gneiss, limestone forms marble, and quartz sandstone forms quartzite, so the other pairings are crossed.",{});}]),["Check each parent against its known product."]);
E("es-u3-334-q04",3,["EA12.3.34"],3,"var",varset([function(){return mcq("A layer of limestone is caught beside a large granite intrusion and is strongly heated, while a nearby layer of the same limestone farther from the intrusion is unchanged. Which rock forms in the heated layer, and why only there?","Marble forms there, because the limestone recrystallized where the intrusion's heat reached it.",["Quartzite forms there, because the limestone recrystallized where the intrusion's heat reached it.","Marble forms there, because the limestone melted and cooled as a new igneous rock.","Slate forms there, because the limestone was squeezed by the intrusion's weight."],"Limestone recrystallizes into marble under the heat of contact metamorphism. The change is confined to the aureole beside the intrusion, which is why the same limestone farther away is unchanged. Marble forms by recrystallization, not melting.",{});}]),["Name the metamorphic product of limestone, then match the process."]);

/* ----- EA12.3.35: Contrast the two types of metamorphism ----- */
E("es-u3-335-q01",3,["EA12.3.35"],1,"var",varset([function(){return mcq("Which occurs at the boundary of an igneous intrusion and existing rock?","contact metamorphism",["cross bedding","pillow basalts","regional metamorphism"],"Where an igneous intrusion meets existing rock, the heat bakes the rock at the boundary: contact metamorphism.",{});}]),["Intrusion boundaries are the classic setting for one type."]);
E("es-u3-335-q02",3,["EA12.3.35"],2,"var",varset([function(){return mcq("Which is the main factor causing contact metamorphism?","heat",["chemical fluids","original rock","pressure"],"Heat is the main factor in contact metamorphism, supplied by the nearby magma body; pressure plays a minor role.",{});}]),["Contact metamorphism happens next to something hot."]);
E("es-u3-335-q03",3,["EA12.3.35"],2,"var",varset([function(){return mcq("Which causes a pre-existing rock to experience change when exposed to high heat, chemically-active fluids and low pressure?","contact metamorphism",["cementation","folding","regional metamorphism"],"High heat with chemically active fluids and low pressure describes contact metamorphism, which occurs around igneous intrusions. Regional metamorphism involves high pressure over large areas.",{});}]),["Low pressure rules out the regional type."]);

/* ----- EA12.3.36: Describe the locations where contact metamorphism occurs ----- */
E("es-u3-336-q01",3,["EA12.3.36"],2,"var",varset([function(){return mcq("Where does contact metamorphism take place?","In the rock immediately surrounding a magma body, in a baked zone called an aureole",["Across whole continental regions squeezed and heated during plate collisions","Deep within subduction zones, where pressure is extreme but temperatures stay low","In thick sediment layers buried at the bottoms of deep ocean basins over time"],"Contact metamorphism is local: it bakes the country rock in a zone, or aureole, around an intrusion or beneath a thick lava flow. The other settings describe regional metamorphism or burial.",{});}]),["The word contact points to touching the heat source."]);
E("es-u3-336-q02",3,["EA12.3.36"],1,"var",varset([function(){return mcq("A hornfels, a rock changed only by heat, is found as a thin band along the edge of a granite pluton. Which setting produced it?","The contact zone at the pluton's margin",["The centre of a folded mountain belt","The floor of a deep ocean trench","The interior of the pluton itself"],"A thin baked band at an intrusion's edge is the classic location of contact metamorphism; the pluton's own interior is igneous rock, not metamorphosed country rock.",{});}]),["Look for the margin, where hot rock touched cooler rock."]);

/* ----- EA12.3.37: Describe how contact metamorphism can be used to distinguish between a buried lava flow and an intrusion of magma ----- */
E("es-u3-337-q01",3,["EA12.3.37"],2,"var",varset([function(){return mcq("A tabular igneous body is found between sedimentary layers, and the rock both above and below it has been baked by heat. What does the baking pattern show?","The body is an intrusive sill: magma forced its way between the layers and heated the rock on both sides.",["The body is a buried lava flow: lava ran over the lower layer and was later covered by sediment.","The body is a fault block that was heated by friction as it moved.","The body is a metamorphic layer that formed during regional metamorphism."],"An intrusive sill bakes the rock above and below it, because hot magma was injected between existing layers. A buried lava flow can only bake the rock beneath it; the sediment above was deposited later, after the lava cooled.",{});}]),["Compare which side, or sides, of the body show heat effects."]);
E("es-u3-337-q02",3,["EA12.3.37"],1,"var",varset([function(){return mcq("Only the rock underneath a tabular igneous layer shows heat alteration, and the layer's top is weathered. What is the layer most likely to be?","A buried lava flow",["An intrusive sill","A granite batholith","A metamorphic aureole"],"A lava flow bakes only the ground it ran over, and its exposed top weathers before sediment buries it. A sill, injected between layers, would bake the rock above it too.",{});}]),["One-sided baking is the giveaway."]);

/* ----- EA12.3.38: Describe the locations where regional metamorphism occurs ----- */
E("es-u3-338-q01",3,["EA12.3.38"],2,"var",varset([function(){return mcq("Which has the least impact during regional metamorphism?","faulting",["fluids","pressure","temperature"],"Regional metamorphism is driven by temperature, pressure and fluids deep in mountain belts; faulting, a surface and near-surface process, has the least impact on it.",{});}]),["Three of the choices are the recognized agents of metamorphism."]);
E("es-u3-338-q02",3,["EA12.3.38"],1,"var",varset([function(){return mcq("Which type of metamorphism produces the greatest volume of metamorphic rock?","Regional metamorphism",["Burial metamorphism","Contact metamorphism","Shock metamorphism"],"Regional metamorphism acts over the huge volumes of rock caught in mountain building, so it produces far more metamorphic rock than the small zones around intrusions.",{});}]),["Think about the size of the area each type affects."]);

